GAMES_DATA.bank=[{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Quantum Mechanics","d":"The physics theory describing how nature behaves at the smallest scales: particles can be in combinations of states, act like waves."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Qubit","d":"The basic unit of quantum information."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Classical Bit","d":"The unit inside every conventional computer: a switch that is definitively 0 or 1."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Superposition","d":"A qubit's ability to be in a combination of 0 and 1 at once, described by amplitudes."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Quantum State","d":"The complete description of what a qubit or system of qubits is doing at a moment: the full set of amplitudes across all possible outcomes."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Measurement","d":"The act of reading a qubit at the end of a computation."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Probability Amplitude","d":"The numbers describing a quantum state."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Coherence","d":"How long a qubit maintains its delicate quantum behaviour before the environment disturbs it."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Decoherence","d":"The loss of quantum behaviour when a system interacts with its surroundings: heat, vibration, stray fields."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Bloch Sphere","d":"A visual map of a single qubit's state as a point on a sphere."},{"f":"quantum","t":"quantum-keywords","g":"The Basics","n":"Quantum Register","d":"A group of qubits working together as one unit of computation, the quantum analogue of a classical register, but holding amplitudes for every combination of its qubits."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Entanglement","d":"A link between qubits where their states are correlated more strongly than classical physics allows."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Quantum Interference","d":"Amplitudes for wrong answers cancel each other while amplitudes for right answers add up."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Quantum Tunnelling","d":"A particle can pass through an energy barrier it classically could not climb over."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"No-Cloning Theorem","d":"A proven limit: an unknown quantum state cannot be perfectly copied."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Quantum Teleportation","d":"A protocol that transfers one qubit's state to a distant qubit using an entangled pair plus an ordinary classical message."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Bell Pair","d":"Two qubits in a maximally entangled state, the standard shared resource consumed by teleportation, networking and many algorithms."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Uncertainty Principle","d":"Heisenberg's limit: certain pairs of properties cannot both be known with arbitrary precision at the same time."},{"f":"quantum","t":"quantum-keywords","g":"Quantum Phenomena","n":"Wave Function","d":"The mathematical object describing a quantum state and how it evolves."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Quantum Gate","d":"An operation that rotates or flips qubit states, the building block of quantum programs, analogous to logic gates in classical chips but reversible and smooth."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Hadamard Gate","d":"The gate that puts a qubit into an even superposition of 0 and 1."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Pauli Gates","d":"The three fundamental single-qubit operations, X, Y and Z, named after Wolfgang Pauli."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"CNOT Gate","d":"A two-qubit gate that flips the second qubit only when the first is 1."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Quantum Circuit","d":"A quantum program drawn as a score: horizontal lines are qubits, boxes are gates, read left to right, ending in measurement."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Circuit Depth","d":"The number of sequential steps in a circuit."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Gate Fidelity","d":"How accurately a gate performs its intended operation, expressed as a percentage."},{"f":"quantum","t":"quantum-keywords","g":"Gates & Circuits","n":"Quantum Volume","d":"A benchmark (from IBM) combining qubit count, gate quality, connectivity and software into one score, designed to reward usable machines over large ones."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Quantum Computer","d":"A machine that processes information using qubits, gates and measurement."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"QPU","d":"Quantum Processing Unit: the quantum chip at the heart of the system, the analogue of a CPU or GPU, surrounded by control electronics and often cryogenics."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Superconducting Qubits","d":"Tiny electrical circuits, cooled to near absolute zero, behaving as artificial atoms."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Trapped Ion Qubits","d":"Individual charged atoms held in electromagnetic traps and controlled with lasers."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Photonic Quantum Computing","d":"Computing with photons, particles of light, as the information carriers."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Neutral Atom Qubits","d":"Uncharged atoms held in place by laser tweezers in large, reconfigurable arrays."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Topological Qubits","d":"Microsoft's approach, aiming to store information in exotic states of matter (Majorana zero modes) that are naturally protected from many errors."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Quantum Annealer","d":"A special-purpose quantum machine designed for optimisation problems, built by D-Wave."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Cryogenics","d":"The refrigeration technology, usually a dilution refrigerator, that keeps superconducting chips near absolute zero so their quantum behaviour survives."},{"f":"quantum","t":"quantum-keywords","g":"Hardware & Platforms","n":"Spin Qubits","d":"Qubits stored in the spin of electrons in silicon, the approach Intel and several labs pursue because it can reuse semiconductor manufacturing."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Quantum Algorithm","d":"A procedure designed for a quantum computer that structures interference so correct answers become probable."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Shor's Algorithm","d":"A 1994 algorithm that factors large numbers exponentially faster than known classical methods."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Grover's Algorithm","d":"A search algorithm that finds an item in an unsorted database with a quadratic speedup over classical search."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Quantum Fourier Transform","d":"A core subroutine that finds hidden patterns and periods in data, exponentially faster than its classical counterpart."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"VQE","d":"Variational Quantum Eigensolver: a hybrid algorithm for chemistry and materials problems, splitting work between a small quantum chip and a classical optimiser."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"QAOA","d":"Quantum Approximate Optimisation Algorithm: a hybrid, near-term algorithm for optimisation problems such as scheduling, routing and portfolio construction."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Quantum Simulation","d":"Using a controllable quantum system to model another quantum system, such as a molecule or material, that classical computers cannot model exactly."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Quantum Advantage","d":"The point where a quantum computer solves a useful, real-world problem better than the best classical approach, on cost, speed or accuracy."},{"f":"quantum","t":"quantum-keywords","g":"Algorithms","n":"Quantum Supremacy","d":"A 2019 milestone claim (Google) that a quantum machine performed a specific sampling task beyond classical reach."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Noise","d":"Unwanted disturbance from the environment that corrupts quantum states and operations."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Quantum Error","d":"A mistake in a qubit's state or a gate's action, caused by noise."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"NISQ","d":"Noisy Intermediate-Scale Quantum: the current era, defined by John Preskill in 2018."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Physical Qubit","d":"An actual hardware qubit: real, imperfect and error-prone."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Logical Qubit","d":"A protected, error-corrected qubit built by encoding information across many physical qubits."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Quantum Error Correction","d":"Techniques that spread one qubit's information across many, continuously detecting and fixing errors without reading the protected data directly (which no-cloning."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Fault Tolerance","d":"The ability to compute reliably even though components keep failing, achieved when error rates fall below a threshold and correction outruns new errors."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Gate Error Rate","d":"The probability that an operation introduces an error, the inverse of fidelity."},{"f":"quantum","t":"quantum-keywords","g":"Noise, Errors & Scale","n":"Qubit Count","d":"The headline number of physical qubits in a system."},{"f":"quantum","t":"quantum-keywords","g":"Quantum + AI","n":"Quantum Machine Learning","d":"Using quantum circuits to process data or accelerate parts of machine learning."},{"f":"quantum","t":"quantum-keywords","g":"Quantum + AI","n":"Hybrid Quantum-Classical","d":"The near-term computing pattern: a quantum chip handles a small, hard kernel while classical computers do everything else, looping results back and forth."},{"f":"quantum","t":"quantum-keywords","g":"Quantum + AI","n":"Quantum Data","d":"Data that is itself quantum in origin, produced by quantum sensors, experiments or simulations, rather than ordinary classical records converted for a quantum machine."},{"f":"quantum","t":"quantum-keywords","g":"Quantum + AI","n":"Quantum Neural Network","d":"A parameterised quantum circuit trained by adjusting its settings, analogous to training a small neural network."},{"f":"quantum","t":"quantum-keywords","g":"Quantum + AI","n":"Quantum Kernel","d":"A method that uses a quantum circuit to map classical data into a feature space for a conventional machine learning classifier."},{"f":"quantum","t":"quantum-keywords","g":"Quantum + AI","n":"Quantum AI","d":"An umbrella term for combining quantum computing with artificial intelligence."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Quantum Cryptography","d":"Security methods that use quantum physics itself, chiefly quantum key distribution, rather than mathematics alone, to protect communications."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Quantum Key Distribution","d":"A method for sharing encryption keys where any eavesdropping disturbs the quantum states and reveals itself."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Post-Quantum Cryptography","d":"New encryption and signature algorithms that run on ordinary computers but are designed to resist quantum attacks."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Harvest Now, Decrypt Later","d":"An attack strategy: collect encrypted data today, store it, and decrypt it later when a capable quantum computer exists."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Q-Day","d":"The informal name for the day a cryptographically relevant quantum computer can break today's widely used encryption."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Cryptographic Agility","d":"The organisational ability to swap cryptographic algorithms across systems quickly, through inventory, abstraction and testing, rather than emergency rewrites."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Quantum Internet","d":"A future network that connects quantum devices by distributing entanglement, enabling teleportation, networked sensors and linked quantum processors."},{"f":"quantum","t":"quantum-keywords","g":"Communication & Security","n":"Quantum Network","d":"The infrastructure for moving quantum information between devices: entanglement sources, quantum repeaters and links."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"Quantum Sensing","d":"Sensors that exploit quantum effects to measure time, gravity, magnetic fields or motion with extreme precision."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"Quantum Navigation","d":"Positioning and timing using quantum clocks and inertial sensors, working without GPS signals, for submarines, aircraft and infrastructure."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"QRNG","d":"Quantum Random Number Generation: producing genuinely random numbers from quantum processes, used to strengthen keys and security systems."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"Quantum Chemistry","d":"Simulating molecules and reactions on quantum computers to design drugs, fertilisers, catalysts and chemicals that classical simulation cannot handle exactly."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"Quantum Optimisation","d":"Applying annealers and algorithms like QAOA to routing, scheduling, logistics and portfolio problems, seeking better solutions than classical solvers find."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"Quantum Finance","d":"Exploratory work by banks on risk analysis, pricing and portfolio optimisation using quantum algorithms, currently at research and pilot stage."},{"f":"quantum","t":"quantum-keywords","g":"Sensing & Applications","n":"Quantum Materials","d":"Using quantum simulation to design new materials: better batteries, superconductors, solar cells and industrial catalysts."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Readiness","d":"An organisation's preparedness for quantum's impact: knowing its cryptographic exposure, watching relevant use cases."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum-Safe","d":"Describes systems and data protected against quantum attack, usually by migrating to post-quantum cryptography."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum as a Service","d":"Cloud access to quantum hardware, such as IBM Quantum, Microsoft Azure Quantum and Amazon Braket, billed by usage with no hardware to own."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Roadmap","d":"A vendor or national plan describing milestones toward larger, error-corrected machines, usually over five to ten years."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Talent","d":"The scarce workforce spanning quantum physics, engineering, cryogenics, and quantum software."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Ecosystem","d":"The network of hardware vendors, startups, software firms, standards bodies and national programmes shaping the technology's direction and supply chain."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Investment","d":"The funding landscape: venture capital, corporate investment and large state programmes (the US, EU, China, UK and others have committed billions)."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Risk","d":"The leadership view of quantum exposure: cryptographic vulnerability, long-lived data, vendor lock-in, and hype-driven spending, weighed against competitive upside."},{"f":"quantum","t":"quantum-keywords","g":"Business & Leadership","n":"Quantum Literacy","d":"Leadership-level understanding of quantum concepts and vocabulary: enough to evaluate claims, ask the right questions and allocate attention proportionately."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Deutsch Algorithm","d":"The first quantum algorithm ever published (1985): given a black-box function of one bit that is either constant or balanced, it decides which with a single query."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Deutsch-Jozsa Algorithm","d":"The n-bit generalisation of Deutsch's algorithm: it distinguishes a constant function from a balanced one with one oracle query and no error."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Bernstein-Vazirani Algorithm","d":"Given a black-box function f(x) = a.x (mod 2) for a hidden n-bit string a."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Simon's Algorithm","d":"Simon's problem asks for a hidden period s of a function that is two-to-one with f(x) = f(x XOR s)."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"QFT","d":"The quantum analogue of the discrete Fourier transform, mapping a superposition over basis states to a superposition over their Fourier components."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"QPE","d":"Given a unitary U and one of its eigenstates, phase estimation extracts the eigenphase phi (where U|u> = e^(2 pi i phi)|u>) into a register of qubits."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Amplitude Amplification","d":"A generalisation of Grover's search: if a procedure succeeds with probability p."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Amplitude Estimation","d":"Estimates the amplitude a of a marked component of a superposition \u2014 equivalently the expected value of a function \u2014 to precision epsilon using O(1/epsilon) oracle calls."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Quantum Counting","d":"Combines Grover's iteration with phase estimation to count how many items in a database satisfy a search criterion, rather than finding just one."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Quantum Walks","d":"The quantum analogue of a classical random walk, in discrete-time (with a coin register) and continuous-time forms."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Oracle Model","d":"Most early quantum speedups are proven in the query (oracle) model, where the algorithm accesses problem data through a black box and cost is counted in queries."},{"f":"quantum","t":"quantum-algorithms","g":"Core Primitives","n":"Quantum Parallelism","d":"Applying a unitary to a superposition evaluates a function on all inputs at once in the amplitude structure \u2014 but measurement returns only one outcome."},{"f":"quantum","t":"quantum-algorithms","g":"Search & Optimisation","n":"Grover's Algorithm","d":"Searches an unstructured space of N items for a marked one using about (pi/4) sqrt(N) oracle calls, by repeatedly amplifying the marked item's amplitude."},{"f":"quantum","t":"quantum-algorithms","g":"Search & Optimisation","n":"Quantum Annealing","d":"A heuristic optimisation method that encodes a problem as an Ising model or QUBO and slowly evolves the system toward its low-energy state."},{"f":"quantum","t":"quantum-algorithms","g":"Search & Optimisation","n":"Adiabatic Quantum Computing","d":"A model of computation where a system prepared in the ground state of a simple Hamiltonian is evolved slowly enough to remain in the ground state of a final Hamiltonian."},{"f":"quantum","t":"quantum-algorithms","g":"Search & Optimisation","n":"QAOA","d":"A hybrid variational algorithm for combinatorial optimisation: a shallow circuit alternates cost and mixing unitaries with 2p classical parameters."},{"f":"quantum","t":"quantum-algorithms","g":"Search & Optimisation","n":"MaxCut Problem","d":"Partition a graph's vertices into two sets to maximise the number (or weight) of edges crossing between them."},{"f":"quantum","t":"quantum-algorithms","g":"Search & Optimisation","n":"Quadratic vs Exponential Speedup","d":"Quantum speedups come in grades."},{"f":"quantum","t":"quantum-algorithms","g":"Simulation & Chemistry","n":"Hamiltonian Simulation","d":"Simulating the time evolution of a quantum system under its Hamiltonian H \u2014 applying e^(-iHt) to a state."},{"f":"quantum","t":"quantum-algorithms","g":"Simulation & Chemistry","n":"Trotterisation (Product Formulas)","d":"When H is a sum of non-commuting terms, e^(-iHt) is approximated by alternating short evolutions under each term \u2014 the Lie-Trotter-Suzuki product formulas."},{"f":"quantum","t":"quantum-algorithms","g":"Simulation & Chemistry","n":"Quantum Simulation of Chemistry","d":"Computing molecular energies and reaction properties by simulating electrons directly."},{"f":"quantum","t":"quantum-algorithms","g":"Simulation & Chemistry","n":"Electronic Structure Problem","d":"The core computational problem of quantum chemistry: given a molecular Hamiltonian (kinetic energy, electron-nuclear attraction, electron-electron repulsion)."},{"f":"quantum","t":"quantum-algorithms","g":"Simulation & Chemistry","n":"Active Space","d":"A pragmatic reduction used in nearly all quantum chemistry demonstrations."},{"f":"quantum","t":"quantum-algorithms","g":"Simulation & Chemistry","n":"QPE for Chemistry","d":"The fault-tolerant route to ground-state energies: prepare an approximate ground state (often from a classical method)."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Data Encoding","d":"Before any quantum machine learning happens, classical data must be loaded into a quantum state, and the encoding choice defines the model."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Quantum Feature Maps","d":"A feature map embeds classical data into a high-dimensional Hilbert space via a parameterised circuit."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Quantum Kernels","d":"Kernel methods compute pairwise similarities between data points."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"VQE","d":"A hybrid algorithm for ground-state energies: a parameterised circuit (the ansatz) prepares a trial state, a quantum device measures the Hamiltonian's expectation value."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Quantum Neural Networks","d":"Parameterised quantum circuits used as trainable models: data is encoded, a variational circuit processes it, and measured outputs serve as predictions."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Barren Plateaus","d":"In deep or expressive variational circuits, the training landscape becomes exponentially flat: gradient magnitudes shrink as ~2^(-n) with qubit count."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Ansatz Design","d":"The ansatz is the structure of a variational circuit \u2014 which gates, in what pattern, with which parameters."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"QSVM","d":"The family of quantum SVM proposals, from the 2014 HHL-based least-squares SVM (exponential speedup claimed under strong assumptions about data access) to today's."},{"f":"quantum","t":"quantum-algorithms","g":"Quantum Machine Learning","n":"Data Loading Bottleneck","d":"The recurring structural problem of quantum machine learning and quantum data analysis."},{"f":"quantum","t":"quantum-algorithms","g":"Cryptography & Number Theory","n":"Shor's Algorithm","d":"Factors a large integer N by reducing factoring to order finding: pick a random a, find the period r of a^x mod N with a quantum Fourier transform over a superposition."},{"f":"quantum","t":"quantum-algorithms","g":"Cryptography & Number Theory","n":"Order Finding","d":"The quantum core of Shor's algorithm: given a and N, find the smallest r with a^r = 1 (mod N)."},{"f":"quantum","t":"quantum-algorithms","g":"Cryptography & Number Theory","n":"Discrete Logarithm Problem","d":"Given g, h and a prime p, find x with g^x = h (mod p) \u2014 the hard problem under Diffie-Hellman key exchange and (in elliptic-curve form) ECDSA signatures."},{"f":"quantum","t":"quantum-algorithms","g":"Cryptography & Number Theory","n":"HHL","d":"The Harrow-Hassidim-Lloyd algorithm (2009) prepares a quantum state proportional to the solution of a linear system Ax = b, in time polylog(N) for sparse."},{"f":"quantum","t":"quantum-algorithms","g":"Cryptography & Number Theory","n":"Quantum Money & Unclonable States","d":"Wiesner's 1970s idea (published 1983): banknotes carrying quantum states in secret bases."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"Variational Quantum Algorithms","d":"The family of near-term hybrid algorithms \u2014 VQE, QAOA and their descendants \u2014 that split work between a shallow parameterised quantum circuit and a classical optimiser."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"Classical Optimiser Loop","d":"The classical half of every variational algorithm: an optimiser (COBYLA, SPSA, Adam, gradient-based methods) proposes parameters."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"Error Mitigation","d":"A family of techniques that trade extra circuit executions for reduced bias in results from noisy hardware \u2014 zero-noise extrapolation, probabilistic error cancellation."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"ZNE","d":"Run the same circuit at several deliberately amplified noise levels (by stretching pulses or folding gates), measure the observable at each."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"PEC","d":"Characterise each noisy gate's error channel precisely, then implement the inverse (noise-free) operation as a random mixture of implementable noisy operations."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"Circuit Knitting","d":"Cut a circuit too large for one device into subcircuits \u2014 by cutting wires (states) or gates (interactions) \u2014 run the pieces separately."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"Dynamic Circuits","d":"Circuits with mid-circuit measurement and real-time classical feed-forward: measure qubits during execution and let later gates depend on the results within the same run."},{"f":"quantum","t":"quantum-algorithms","g":"Near-Term Hybrid Algorithms","n":"Mid-Circuit Measurement","d":"Measuring a subset of qubits in the middle of a computation without collapsing the rest \u2014 the enabling primitive behind dynamic circuits."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"FTQC","d":"Computation built on logical qubits encoded across many physical qubits, with error correction cycles that detect and fix errors faster than they accumulate."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"Logical Qubits","d":"A logical qubit is quantum information encoded redundantly across many physical qubits (a surface-code patch."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"Magic State Distillation","d":"Eastin-Knill forbids a universal gate set implemented purely transversally."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"Lattice Surgery","d":"The practical method for performing logical operations between surface-code patches: merge two encoded patches along a boundary, measure, then split them."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"Resource Estimation","d":"The discipline of costing a fault-tolerant algorithm end to end: logical qubits, T-count, code distance, physical qubits, runtime and factory footprint."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"T-Count & T-Depth","d":"In fault-tolerant costing, Clifford gates are (relatively) cheap but the non-Clifford T gate consumes distilled magic states."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"Qubitisation","d":"A fault-tolerant simulation framework that embeds a Hamiltonian into a unitary walk operator whose phases encode the Hamiltonian's eigenvalues exactly \u2014 no Trotter error."},{"f":"quantum","t":"quantum-algorithms","g":"Fault-Tolerant Algorithms","n":"Surface Code","d":"The leading quantum error-correcting code: data and measurement qubits on a 2D lattice, with local stabiliser checks that reveal errors without revealing data."},{"f":"quantum","t":"quantum-algorithms","g":"Limits & Complexity","n":"BQP","d":"The complexity class of problems a quantum computer can solve in polynomial time with error probability at most 1/3 \u2014 the quantum analogue of BPP."},{"f":"quantum","t":"quantum-algorithms","g":"Limits & Complexity","n":"Query Complexity","d":"The study of how many oracle queries an algorithm needs, and the source of both the field's cleanest speedups (Grover, Simon) and its cleanest limits."},{"f":"quantum","t":"quantum-algorithms","g":"Limits & Complexity","n":"Limits of Quantum Speedup","d":"The accumulated no-go results that bound the field: unstructured problems cap at quadratic (Grover optimality); NP-complete problems resist black-box quantum attack."},{"f":"quantum","t":"quantum-algorithms","g":"Limits & Complexity","n":"Quantum Advantage Claims","d":"A recurring cycle since 2019: a supremacy or utility claim on a contrived task (random circuit sampling, boson sampling, a mitigated expectation value)."},{"f":"quantum","t":"quantum-algorithms","g":"Limits & Complexity","n":"Classical Simulability","d":"Large classes of quantum circuits are efficiently simulable classically: stabiliser circuits (Gottesman-Knill theorem)."},{"f":"quantum","t":"quantum-algorithms","g":"Limits & Complexity","n":"Dequantisation","d":"Starting with Ewin Tang's 2018 result (as a teenager) on recommendation systems."},{"f":"quantum","t":"quantum-hardware","g":"Qubit Technologies","n":"Physical Qubit","d":"A physical qubit is a real, imperfect quantum device \u2014 a superconducting circuit, a trapped ion, an atom \u2014 that holds one unit of quantum information."},{"f":"quantum","t":"quantum-hardware","g":"Qubit Technologies","n":"Logical Qubit","d":"A logical qubit is an error-corrected qubit built from many physical qubits acting as one."},{"f":"quantum","t":"quantum-hardware","g":"Qubit Technologies","n":"Qubit Modalities","d":"A modality is the physical technology used to build qubits: superconducting circuits, trapped ions, neutral atoms, photons, silicon spins and more exotic options."},{"f":"quantum","t":"quantum-hardware","g":"Qubit Technologies","n":"Two-Level System","d":"A qubit works because nature offers systems with two distinguishable states that can also exist in superposition \u2014 the ground and excited states of an atom."},{"f":"quantum","t":"quantum-hardware","g":"Qubit Technologies","n":"Qubit Coupling","d":"Coupling is how qubits are made to interact so two-qubit gates \u2014 the operations that create entanglement \u2014 can run between them."},{"f":"quantum","t":"quantum-hardware","g":"Qubit Technologies","n":"Native Gate Set","d":"Every hardware platform natively performs a small set of gates \u2014 the operations its physics does best \u2014 and compilers translate algorithms into that set."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Superconducting Qubit","d":"Superconducting qubits are tiny electrical circuits, cooled until electrical resistance vanishes, whose quantum states are controlled with microwave pulses."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Transmon","d":"The transmon is the dominant superconducting qubit design, used by IBM, Google, Rigetti and others."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Flux Qubit","d":"A flux qubit is a superconducting loop interrupted by Josephson junctions, whose two states are currents circulating clockwise or anticlockwise."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Josephson Junction","d":"A Josephson junction is two superconductors separated by an insulating layer only a few atoms thick, thin enough for Cooper pairs to tunnel through."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Microwave Resonator","d":"Superconducting qubits are controlled and read out through microwave resonators \u2014 on-chip structures that resonate at a specific frequency."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"IBM Heron Processor","d":"Heron is IBM's superconducting processor family, introduced in 2023 with 133 qubits and tunable couplers that reduce crosstalk and errors compared with its Eagle."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Google Willow Chip","d":"Willow is Google's 105-qubit superconducting processor, announced in December 2024."},{"f":"quantum","t":"quantum-hardware","g":"Superconducting","n":"Google Sycamore Processor","d":"Sycamore is Google's earlier superconducting processor, famous for the 2019 quantum supremacy experiment."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Trapped-Ion Qubit","d":"Trapped-ion qubits store information in individual charged atoms held in place by electromagnetic fields and manipulated with laser pulses."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Ion Chain","d":"An ion chain is a line of trapped ions sharing collective vibrational modes, which act as a bus connecting qubits for entangling gates."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Laser Cooling","d":"Laser cooling uses precisely tuned laser light to slow ions almost to a standstill, removing thermal motion that would corrupt quantum states."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Neutral-Atom Array","d":"Neutral-atom processors trap hundreds or thousands of uncharged atoms \u2014 usually rubidium or strontium \u2014 in grids of laser light."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Rydberg Atoms","d":"A Rydberg atom has an electron excited to a very large orbit, making it hugely sensitive to its neighbours."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Optical Tweezers","d":"Optical tweezers are tightly focused laser beams that each trap a single atom, forming the reconfigurable grids of neutral-atom processors."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Quantinuum H-Series","d":"Quantinuum \u2014 formed from Honeywell Quantum Solutions and Cambridge Quantum \u2014 builds trapped-ion systems in its H-Series."},{"f":"quantum","t":"quantum-hardware","g":"Trapped Ions & Neutral Atoms","n":"Atom Computing Systems","d":"Atom Computing builds neutral-atom processors using nuclear-spin qubits in strontium atoms, aimed squarely at large scale."},{"f":"quantum","t":"quantum-hardware","g":"Photonic & Silicon","n":"Photonic Qubit","d":"Photonic qubits encode information in particles of light \u2014 in their path, polarisation or timing \u2014 and process it with beam splitters, phase shifters and detectors."},{"f":"quantum","t":"quantum-hardware","g":"Photonic & Silicon","n":"Continuous Variables","d":"Continuous-variable quantum computing encodes information in the smooth amplitudes of light waves rather than in discrete two-level states."},{"f":"quantum","t":"quantum-hardware","g":"Photonic & Silicon","n":"Silicon Spin Qubit","d":"Silicon spin qubits store information in the spin of a single electron or nucleus inside a silicon quantum dot, controlled by microwave or electric pulses."},{"f":"quantum","t":"quantum-hardware","g":"Photonic & Silicon","n":"Quantum Dots","d":"Semiconductor quantum dots are nanoscale regions that confine a single electron, creating an artificial atom whose spin or charge serves as a qubit."},{"f":"quantum","t":"quantum-hardware","g":"Photonic & Silicon","n":"Photonic Interconnects","d":"Photonic interconnects link separate quantum processors with optical fibres, entangling them through photons so many small machines act as one large one."},{"f":"quantum","t":"quantum-hardware","g":"Photonic & Silicon","n":"PsiQuantum Approach","d":"PsiQuantum is pursuing fault-tolerant photonic computing at the million-physical-qubit scale, manufacturing its chips in semiconductor fabs with GlobalFoundries."},{"f":"quantum","t":"quantum-hardware","g":"Exotic Approaches","n":"Topological Qubit","d":"A topological qubit would store information in the braided world-lines of exotic quasiparticles."},{"f":"quantum","t":"quantum-hardware","g":"Exotic Approaches","n":"Majorana Modes","d":"Majorana zero modes are quasiparticle states predicted to appear at the ends of certain superconducting nanowires, behaving as their own antiparticles."},{"f":"quantum","t":"quantum-hardware","g":"Exotic Approaches","n":"Microsoft Majorana 1","d":"Majorana 1 is Microsoft's first chip built around a material stack it calls a topoconductor, intended to host Majorana modes."},{"f":"quantum","t":"quantum-hardware","g":"Exotic Approaches","n":"Diamond NV Centres","d":"A nitrogen-vacancy centre is a defect in diamond \u2014 a nitrogen atom beside a missing carbon atom \u2014 whose electron spin forms a qubit that works at room temperature."},{"f":"quantum","t":"quantum-hardware","g":"Exotic Approaches","n":"Molecular Qubits","d":"Molecular qubits are designer molecules, synthesised by chemists, whose spin states act as qubits \u2014 identical by construction and tunable atom by atom."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Dilution Refrigerator","d":"The dilution refrigerator is the distinctive golden chandelier inside most quantum computers."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Millikelvin Cryogenics","d":"Millikelvin cryogenics is the engineering discipline of creating and holding temperatures near absolute zero."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Control Electronics","d":"Control electronics generate the precisely shaped microwave and laser pulses that operate qubits, and process the signals that read them out."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Cryo-CMOS","d":"Cryo-CMOS means building control circuits from standard CMOS transistors that operate inside the refrigerator, at temperatures of a few kelvin or below."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Wiring Bottleneck","d":"Every qubit needs control and readout lines, and in today's machines most run from room temperature down through the fridge to the chip."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Calibration","d":"Quantum processors drift: qubit frequencies, pulse shapes and couplings wander with temperature and time."},{"f":"quantum","t":"quantum-hardware","g":"Cryogenics & Control","n":"Qubit Fabrication","d":"Fabrication is where quantum hardware meets manufacturing reality."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"T1","d":"T1 measures how long a qubit survives in its excited state before decaying to its ground state \u2014 its energy lifetime."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"T2","d":"T2 measures how long a qubit keeps its phase \u2014 the delicate timing relationship that superposition depends on \u2014 before noise scrambles it."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"Gate Fidelity","d":"Gate fidelity is the probability that an operation does exactly what was intended, measured by benchmarking protocols such as randomised benchmarking."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"Readout Fidelity","d":"Readout fidelity measures how accurately the machine can tell which state a qubit was in at measurement."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"Quantum Volume","d":"Quantum Volume is a benchmark combining qubit count, fidelity, connectivity and compiler quality into one number."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"CLOPS","d":"CLOPS measures how fast a quantum system executes circuit layers, combining gate speed with the classical overhead of control, compilation hand-offs and readout."},{"f":"quantum","t":"quantum-hardware","g":"Metrics That Matter","n":"Physical Error Rate","d":"The physical error rate is the probability that a basic operation or idle moment introduces an error on a physical qubit."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"IBM Quantum","d":"IBM runs the longest-running industrial quantum programme, offering superconducting systems through the cloud since 2016."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Google Quantum AI","d":"Google's quantum programme produced the field's two loudest milestones: the 2019 Sycamore supremacy experiment and Willow's 2024 below-threshold error correction."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"IonQ","d":"IonQ builds trapped-ion systems and was the first pure-play quantum company to list publicly, via a SPAC merger in 2021."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Rigetti Computing","d":"Rigetti is a full-stack superconducting company operating its own fabrication facility, Fab-1 in California, and selling cloud access to its Aspen and Ankaa systems."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"IQM Quantum","d":"IQM is a Finnish superconducting company selling complete systems, including on-premises machines for supercomputing centres and universities."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Pasqal","d":"Pasqal is a French neutral-atom company co-founded by Nobel laureate Alain Aspect, building analogue and increasingly digital quantum systems."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Quandela","d":"Quandela is a French photonic company whose Perceval software platform and photonic processors target optical quantum computing."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Xanadu","d":"Xanadu is a Canadian photonic company whose PennyLane software is a leading tool for quantum machine learning research."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Amazon Braket","d":"Amazon Braket is AWS's quantum cloud service, giving access to hardware from IonQ, Rigetti, IQM and others, plus simulators, through one AWS account."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"Microsoft Azure Quantum","d":"Azure Quantum aggregates hardware from Quantinuum, IonQ, Pasqal and others into Microsoft's cloud, paired with a strong chemistry and materials simulation story."},{"f":"quantum","t":"quantum-hardware","g":"Platforms & Vendors","n":"D-Wave Systems","d":"D-Wave is the industry's oldest quantum company, commercialising quantum annealers since 2011 for optimisation-style problems."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"CRQC","d":"A quantum computer powerful and error-corrected enough to break today's public-key cryptography, such as RSA-2048 or elliptic-curve systems."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"HNDL","d":"An attack in which adversaries intercept and store encrypted traffic today, planning to decrypt it once a cryptographically relevant quantum computer exists."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"Mosca's Inequality","d":"A simple planning test from quantum-risk researcher Michele Mosca."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"RSA","d":"RSA protects keys and signatures by the difficulty of factoring a very large number into two primes."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"ECC","d":"Elliptic-curve cryptography, including ECDH key exchange and ECDSA and EdDSA signatures, rests on the discrete logarithm problem over elliptic curves."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"Grover's Effect on Symmetric Crypto","d":"Grover's algorithm speeds up brute-force search, effectively halving the security bits of symmetric keys: AES-128 drops to roughly 64 bits of quantum resistance."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"AES-256","d":"AES-256 is the symmetric cipher recommended for data that must stay secret for decades, including against quantum attackers."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"SHA-2 & SHA-3 Under Quantum Attack","d":"Hash functions such as SHA-256 and SHA3-256 are used for integrity, signatures and password storage."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"Data Lifetime Classification","d":"Sorting information by how long it must remain confidential: months, years or decades."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"SNDL","d":"Store Now, Decrypt Later is the same attack pattern as Harvest Now, Decrypt Later, under the name used by several allied governments and security agencies."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"Shor's Algorithm","d":"The 1994 algorithm by Peter Shor that solves factoring and discrete logarithms exponentially faster than any known classical method."},{"f":"quantum","t":"quantum-security","g":"The Quantum Threat","n":"Q-Day","d":"Q-Day is the informal name for the moment a cryptographically relevant quantum computer becomes operational."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"ML-KEM","d":"The primary NIST standard for post-quantum key establishment, derived from CRYSTALS-Kyber."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"ML-DSA","d":"The primary NIST standard for post-quantum digital signatures, derived from CRYSTALS-Dilithium."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"SLH-DSA","d":"A signature standard built only on hash functions, derived from SPHINCS+, with security assumptions as conservative as they come."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"FIPS 203","d":"The Federal Information Processing Standard that specifies ML-KEM, published by NIST in final form in August 2024."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"FIPS 204","d":"The FIPS standard specifying ML-DSA as the primary post-quantum digital signature algorithm, finalised in August 2024."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"FIPS 205","d":"The FIPS standard specifying SLH-DSA, the stateless hash-based signature scheme, finalised in August 2024."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"FN-DSA","d":"A forthcoming NIST signature standard based on the Falcon scheme, notable for the smallest signatures among the post-quantum options."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"LMS & XMSS","d":"Hash-based signature schemes standardised earlier in NIST SP 800-208, built from one-time signatures chained in Merkle trees."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"CNSA 2.0","d":"The NSA's published suite and timetable for US national security systems, widely used as a de facto migration benchmark elsewhere."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"NIST IR 8547","d":"NIST's transition guidance describing how quantum-vulnerable algorithms will be deprecated in US federal standards."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"KEM","d":"The post-quantum replacement pattern for public-key encryption and key exchange: one party encapsulates a random secret under a public key."},{"f":"quantum","t":"quantum-security","g":"NIST Standards & Algorithms","n":"HQC","d":"A code-based key encapsulation mechanism NIST selected in 2025 for standardisation as a backup to ML-KEM."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"PQC","d":"The multi-year programme of replacing quantum-vulnerable public-key cryptography across protocols, products and infrastructure with the NIST standards."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"Hybrid Certificates & Key Exchange","d":"Running classical and post-quantum cryptography together so a connection or certificate is safe if either component holds."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"TLS","d":"Upgrading the protocol behind HTTPS and most secure connections to negotiate post-quantum key exchange, and later post-quantum certificates."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"X.509","d":"The certificate format carrying identities across the internet must absorb much larger post-quantum keys and signatures."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"Code Signing Migration","d":"Moving software and firmware signing to quantum-resistant signatures so that code signed today remains trustworthy for its whole service life."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"PKI","d":"Rebuilding the certificate authorities, registration processes and lifecycle tooling that issue digital identities, this time with post-quantum algorithms."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"HSM","d":"Checking whether the hardware modules that guard your most important keys support post-quantum algorithms, through firmware updates or replacement."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"VPN/IPsec","d":"Migrating site-to-site and remote-access VPNs, where IPsec's IKEv2 key exchange is quantum-vulnerable and traffic is a prime harvest target."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"IoT","d":"Connected devices combine weak processors, tight memory, long field lives and, often, no update mechanism at all."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"Pilot & Phased Rollout","d":"Migrating in stages: pilot on low-risk, high-learning systems, then expand by data lifetime and exposure."},{"f":"quantum","t":"quantum-security","g":"Migration in Practice","n":"Testing & Interoperability","d":"Validating that post-quantum implementations actually interoperate across vendors, libraries and middleboxes before production depends on them."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"Crypto-Agility","d":"The organisational ability to swap cryptographic algorithms, keys and certificates quickly, in software and in process, without redesigning systems."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"Cryptographic Inventory","d":"A complete record of where cryptography lives in your estate: algorithms, key lengths, certificates, libraries, protocols and the data they protect."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"CBOM","d":"A machine-readable inventory of cryptographic assets and their properties, modelled on the software bill of materials idea."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"Algorithm Negotiation","d":"The protocol mechanism by which two systems agree which algorithms to use, as TLS does for cipher suites and key-exchange groups."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"Crypto CoE","d":"A small standing team owning cryptographic policy, standards and expertise across the organisation."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"Legacy System Risk","d":"Systems that cannot be upgraded, because the vendor is gone, the code is frozen or the hardware cannot carry new cryptography."},{"f":"quantum","t":"quantum-security","g":"Crypto-Agility & Inventory","n":"Crypto Abstraction Layers","d":"Designing applications to call cryptography through a service or library interface rather than embedding algorithms in code."},{"f":"quantum","t":"quantum-security","g":"Infrastructure & Protocols","n":"PQC Key & Signature Sizes","d":"The practical shock of the transition: post-quantum public keys run from about a kilobyte to several kilobytes."},{"f":"quantum","t":"quantum-security","g":"Infrastructure & Protocols","n":"Bandwidth & Handshake Cost","d":"Larger key shares and certificates mean more bytes and sometimes more round trips when connections are established."},{"f":"quantum","t":"quantum-security","g":"Infrastructure & Protocols","n":"CDN","d":"Content delivery networks terminate much of the world's TLS, so their PQC support decides how fast the public web migrates."},{"f":"quantum","t":"quantum-security","g":"Infrastructure & Protocols","n":"Cloud PQC","d":"The major cloud providers are adding PQC to key management, certificate and library layers on published roadmaps, at different speeds per service."},{"f":"quantum","t":"quantum-security","g":"Infrastructure & Protocols","n":"Middlebox & Ossification Risk","d":"Network middleboxes such as firewalls, proxies and load balancers sometimes reject handshakes they do not recognise or cannot parse at new sizes."},{"f":"quantum","t":"quantum-security","g":"QKD & Quantum Communications","n":"QKD","d":"A technology that uses quantum signals, typically single photons, to agree encryption keys with eavesdropping detection built into the physics."},{"f":"quantum","t":"quantum-security","g":"QKD & Quantum Communications","n":"QKD","d":"The case against broad QKD deployment: it needs dedicated hardware and fibre, works over limited distances without trusted nodes, and does not solve authentication."},{"f":"quantum","t":"quantum-security","g":"QKD & Quantum Communications","n":"Trusted Nodes","d":"Relay points that extend QKD beyond single-link distance by receiving and re-sending keys in classical form."},{"f":"quantum","t":"quantum-security","g":"QKD & Quantum Communications","n":"Quantum Repeaters","d":"Devices that would extend quantum communications over long distances by swapping entanglement between network segments, without reading the quantum information."},{"f":"quantum","t":"quantum-security","g":"Governance, Regulation & Claims","n":"Regulatory Timelines","d":"Governments are converting quantum risk into dated obligations: US federal inventories and migration under CNSA 2.0 and related mandates."},{"f":"quantum","t":"quantum-security","g":"Governance, Regulation & Claims","n":"Board Reporting on Quantum Risk","d":"Presenting quantum risk to the board in the language of exposure and lead time: what data is being harvested, how long migration takes, and where the programme stands."},{"f":"quantum","t":"quantum-security","g":"Governance, Regulation & Claims","n":"Vendor Quantum-Safe Claims","d":"Marketing claims of quantum safety now attach to products with anything from genuine FIPS-standard implementations to unchanged classical cryptography."},{"f":"quantum","t":"quantum-security","g":"Governance, Regulation & Claims","n":"Procurement Requirements","d":"Contract language that makes suppliers carry their share of migration: PQC support dates, crypto-agility commitments, CBOM delivery and algorithm disclosure."},{"f":"quantum","t":"quantum-security","g":"Governance, Regulation & Claims","n":"ETSI","d":"ETSI publishes quantum-safe migration guidance and specifications for operators and enterprises, and runs a dedicated industry specification group for QKD."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Artificial Intelligence","d":"The broad field of building systems that perform tasks associated with human intelligence: understanding language, recognising images."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Machine Learning","d":"A way of building software that learns patterns from examples instead of following hand-written rules."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Deep Learning","d":"Machine learning using large neural networks with many layers, trained on big datasets with powerful hardware."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Narrow AI","d":"AI designed for one specific task or a narrow range of tasks: approving loans, transcribing speech, recommending products."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"AGI","d":"Artificial General Intelligence: a hypothetical system that could learn and perform any intellectual task a human can, across domains."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Algorithm","d":"A defined procedure a computer follows to turn inputs into outputs: a recipe of steps."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Model","d":"The trained artefact that an algorithm produces from data: the thing that actually makes predictions or generates text in production."},{"f":"ai","t":"ai-keywords","g":"Foundations","n":"Turing Test","d":"A test proposed by Alan Turing in 1950: if a human judge, chatting by text, cannot reliably tell the machine from a person, the machine is said to pass."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Training","d":"The phase where a model learns from data: it makes predictions, measures its errors, and adjusts its internal weights to do better."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Inference","d":"Using a trained model to make a prediction or generate an answer on new data."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Dataset","d":"The collection of examples used to train or evaluate a model: documents, images, transactions, recordings, usually with labels or correct answers attached."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Parameters","d":"The internal numerical settings of a model, learned during training, that define how it transforms inputs into outputs."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Weights","d":"The most important parameters in a neural network: numbers that set how strongly each connection influences the result."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Overfitting","d":"When a model memorises its training examples instead of learning patterns that transfer, so it performs brilliantly on data it has seen and poorly on new data."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Generalisation","d":"A model's ability to perform well on new, unseen cases, not just its training examples."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Supervised Learning","d":"Learning from examples that come with the correct answers attached, called labels: emails marked spam or not, loans marked repaid or defaulted."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Unsupervised Learning","d":"Learning from data without labels, by finding structure on its own: grouping similar customers, flagging unusual transactions, compressing data into useful patterns."},{"f":"ai","t":"ai-keywords","g":"How Machines Learn","n":"Reinforcement Learning","d":"Learning by trial and error: an agent takes actions, receives rewards or penalties, and gradually learns a strategy that maximises reward."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Classification","d":"An AI task where the output is a category: fraud or legitimate, urgent or routine, which product, which language."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Regression","d":"An AI task where the output is a number: next month's demand, a delivery time, a credit risk score, a price."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Clustering","d":"Grouping items by similarity without predefined categories: customers who behave alike, documents on similar topics, machines with similar sensor patterns."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Natural Language Processing","d":"The branch of AI that works with human language: understanding, searching, summarising, translating and generating text and speech."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Computer Vision","d":"AI that interprets images and video: inspecting products on a line, reading documents, counting inventory, monitoring safety compliance."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Speech Recognition","d":"Technology that converts spoken language into text, also called speech-to-text."},{"f":"ai","t":"ai-keywords","g":"Types of AI Systems","n":"Recommendation Systems","d":"AI that predicts what a user will value next: products, content, people, actions."},{"f":"ai","t":"ai-keywords","g":"Neural Networks & Compute","n":"Neural Network","d":"A computing structure loosely inspired by the brain: layers of simple units, each combining inputs with learned weights and passing a signal onward."},{"f":"ai","t":"ai-keywords","g":"Neural Networks & Compute","n":"Transformer","d":"The neural network architecture behind virtually all modern language models, introduced in 2017."},{"f":"ai","t":"ai-keywords","g":"Neural Networks & Compute","n":"Attention","d":"The mechanism that lets a transformer decide which parts of the input matter most for each word it processes: in a long contract."},{"f":"ai","t":"ai-keywords","g":"Neural Networks & Compute","n":"GPU","d":"Graphics Processing Unit: a chip built to do many simple calculations in parallel, originally for video games and graphics."},{"f":"ai","t":"ai-keywords","g":"Neural Networks & Compute","n":"AI Accelerator","d":"Any specialised hardware designed to run AI workloads faster or more cheaply than general-purpose chips: GPUs, Google's TPUs, and dedicated AI chips in cloud servers."},{"f":"ai","t":"ai-keywords","g":"Neural Networks & Compute","n":"Foundation Model","d":"A very large model trained on broad data that can be adapted to many different tasks: writing, coding, analysis, image work."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Generative AI","d":"AI that creates new content: text, images, audio, video, code."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Large Language Model","d":"A foundation model trained on enormous amounts of text to predict and generate language."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Token","d":"The unit of text an LLM reads and writes: a chunk that may be a word, part of a word, or punctuation."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Context Window","d":"The maximum amount of text, measured in tokens, that a model can consider at once: your prompt, the documents you attach."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Prompt","d":"The instruction and material you give a model: the question, context, examples and format you want back."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Temperature","d":"A setting that controls how random a model's word choices are."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Multimodal","d":"Describes a model that works across more than one type of input or output: text with images, audio, video or documents."},{"f":"ai","t":"ai-keywords","g":"Generative AI & LLMs","n":"Diffusion Model","d":"The technique behind most modern image and video generators."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"Prompt Engineering","d":"The craft of designing prompts and surrounding instructions so a model reliably produces the format, tone and reasoning a task needs: clear instructions, examples."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"RAG","d":"Retrieval-Augmented Generation: before answering, the system searches your own documents or data, retrieves the relevant passages."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"Embedding","d":"A way of converting text (or images and other data) into a list of numbers, called a vector, that captures meaning: similar meanings get similar numbers."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"Vector Database","d":"A database specialised in storing embeddings and finding the closest matches to a query's embedding extremely fast, across millions of documents."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"Fine-tuning","d":"Taking a pre-trained model and training it further on your specific examples so it adopts your formats, terminology and behaviour."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"RLHF","d":"Reinforcement Learning from Human Feedback: humans rank model answers, those rankings train a reward signal, and the model is optimised to produce answers humans prefer."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"Grounding","d":"Anchoring a model's output in verifiable source material: retrieved documents, database records, tool results."},{"f":"ai","t":"ai-keywords","g":"Working with LLMs","n":"Hallucination","d":"When a model produces fluent, confident output that is false: invented citations, wrong figures, non-existent policies."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"API","d":"Application Programming Interface: the standard way software systems request services from each other."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"Latency","d":"The delay between sending a request and receiving a usable response."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"Benchmark","d":"A standardised test used to compare models: exam-style questions, coding tasks, reasoning problems."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"Evaluation","d":"The discipline of measuring whether an AI system actually works: testing on representative examples, scoring quality, tracking failures and re-testing after every change."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"AI Agent","d":"An AI system that goes beyond answering: it plans steps, uses tools such as search, databases and software actions, and works toward a goal with limited human direction."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"Copilot","d":"An AI assistant embedded inside a tool a person already uses: drafting in documents, suggesting code in an editor, summarising in a CRM."},{"f":"ai","t":"ai-keywords","g":"AI in Practice","n":"Human-in-the-Loop","d":"A design where a person reviews, approves or corrects AI output at defined points before consequences happen: payments released, letters sent, records changed."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Bias","d":"Systematic unfairness or skew in AI outputs, usually inherited from training data, labels or the way a problem was framed: who was represented."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Fairness","d":"Whether an AI system treats people and groups equitably in its decisions and errors: who gets approved, flagged, served or mistaken."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Explainability","d":"The ability to describe why a model produced a particular output in terms a human can inspect: which factors mattered, what would change the result."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Alignment","d":"The problem of making AI systems pursue the goals their creators actually intend, rather than literal, gamed or unintended interpretations of those goals."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"AI Safety","d":"The field and practice of ensuring AI systems behave reliably and do not cause harm: through testing, monitoring, access controls and limits on use."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Guardrails","d":"Controls placed around a model to keep behaviour within bounds: input and output filters, topic restrictions, format enforcement, escalation to humans."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Red Teaming","d":"Deliberately attacking your own AI system before others do: crafting prompts and scenarios that try to extract data, bypass guardrails or produce harmful output."},{"f":"ai","t":"ai-keywords","g":"Risks & Limits","n":"Data Privacy","d":"Protecting personal and confidential information across the AI lifecycle: what data is collected, sent to providers, stored in logs."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"AI Regulation (EU AI Act)","d":"Laws governing how AI is built and used."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"AI Governance","d":"The organisational system for deciding which AI is used, for what, with what data, under whose accountability: policies, approval paths, model inventories."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"Build vs Buy","d":"The decision between developing AI capability in-house and consuming it from vendors or platforms."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"Data Strategy","d":"The plan for what data the organisation collects, cleans, governs and makes usable, treated as a strategic asset."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"AI Strategy","d":"A deliberate plan linking AI investments to business outcomes: which problems, in which order, build or buy, with what data, talent, governance and measures of success."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"Measuring AI ROI","d":"Evaluating whether AI pays: time saved, quality improved, revenue created or risk reduced, against the full cost of licences, integration, data preparation."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"AI Literacy","d":"The working understanding of AI across an organisation: what it does, where it fails, how to use it well and what the rules are."},{"f":"ai","t":"ai-keywords","g":"Governance, Business & Strategy","n":"AI Ethics","d":"The principles and choices about how AI should be used: fairness, transparency, accountability."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"ChatGPT","d":"OpenAI's general-purpose AI assistant and the product that brought generative AI to the mainstream."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"Claude","d":"Anthropic's AI assistant, known for careful long-form writing, nuanced reasoning and strong handling of long documents."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"Google Gemini","d":"Google's flagship AI assistant, deeply integrated with Google Search, Android and the Google account ecosystem."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"Microsoft Copilot (Consumer)","d":"Microsoft's free consumer AI assistant, built into Windows, Edge and a standalone app, and powered largely by OpenAI models."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"Grok","d":"xAI's AI assistant, integrated with the X platform and known for real-time access to X posts and a less filtered conversational style."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"DeepSeek","d":"A Chinese AI lab whose open-weight models drew global attention for delivering strong reasoning at unusually low cost."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"Poe","d":"Quora's multi-model platform: one subscription and one interface giving access to models from OpenAI, Anthropic, Google and others, plus millions of user-created bots."},{"f":"ai","t":"ai-tools","g":"AI Assistants & Chatbots","n":"Meta AI","d":"Meta's AI assistant, built into WhatsApp, Instagram, Facebook and Messenger, and powered by the open-weight Llama models."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"Perplexity","d":"An AI answer engine that responds to questions with cited sources gathered live from the web."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"NotebookLM","d":"Google's research notebook: you upload documents, recordings or links, and it answers strictly from those sources with citations."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"Elicit","d":"A research assistant built for evidence-based work: it searches academic literature, extracts methods and findings into structured tables."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"Consensus","d":"An AI search engine over peer-reviewed research that answers questions by synthesising study findings, and even gauges how far the evidence agrees."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"ChatGPT Deep Research","d":"OpenAI's agentic research mode: give it a question and it plans, browses many sources over several minutes and returns a structured, cited report."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"Gemini Deep Research","d":"Google's agentic research feature inside Gemini: it builds a research plan, browses the web extensively and produces a multi-page cited report."},{"f":"ai","t":"ai-tools","g":"AI Search & Research","n":"SciSpace","d":"A research platform for reading and understanding scientific papers: it explains dense passages in plain language."},{"f":"ai","t":"ai-tools","g":"Writing & Productivity","n":"Grammarly","d":"The most widely adopted AI writing layer: it checks grammar, tone and clarity everywhere you type, and now generates and rewrites text in context."},{"f":"ai","t":"ai-tools","g":"Writing & Productivity","n":"Notion AI","d":"AI built into the Notion workspace: it drafts and edits pages, summarises meeting notes and documents, and answers questions across the whole workspace."},{"f":"ai","t":"ai-tools","g":"Writing & Productivity","n":"Jasper","d":"A marketing-focused AI writing platform with brand voice controls, campaign templates and team workflows."},{"f":"ai","t":"ai-tools","g":"Writing & Productivity","n":"Lex","d":"A minimalist AI word processor built for serious writers: a clean page, with AI help summoned on demand for edits, rewrites and unsticking a draft."},{"f":"ai","t":"ai-tools","g":"Writing & Productivity","n":"Sudowrite","d":"An AI writing tool built specifically for fiction: it helps novelists brainstorm, expand scenes, generate description and push through blocks."},{"f":"ai","t":"ai-tools","g":"Writing & Productivity","n":"QuillBot","d":"A paraphrasing and rewriting tool used heavily by students and professionals to rephrase text, adjust tone and summarise."},{"f":"ai","t":"ai-tools","g":"Meetings & Communication","n":"Otter.ai","d":"An AI meeting assistant that joins calls, records, transcribes and summarises them, and answers questions across your meeting history."},{"f":"ai","t":"ai-tools","g":"Meetings & Communication","n":"Fireflies.ai","d":"A meeting assistant that records and transcribes calls across Zoom, Meet and Teams, then generates summaries, action items and searchable conversation analytics."},{"f":"ai","t":"ai-tools","g":"Meetings & Communication","n":"Granola","d":"A meeting notes app that enhances your own rough notes instead of sending a bot into the call."},{"f":"ai","t":"ai-tools","g":"Meetings & Communication","n":"Zoom AI Companion","d":"AI features built into Zoom: meeting summaries, in-meeting questions, chat and email drafting, and whiteboard help, included for paid Zoom accounts."},{"f":"ai","t":"ai-tools","g":"Meetings & Communication","n":"Read AI","d":"A meeting intelligence platform that transcribes and summarises calls and adds engagement and sentiment analytics, coaching speakers on clarity and inclusion."},{"f":"ai","t":"ai-tools","g":"Meetings & Communication","n":"Fathom","d":"A free AI notetaker for Zoom, Meet and Teams that records, transcribes and summarises calls, with highlight clipping for sharing key moments."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"Midjourney","d":"The benchmark AI image generator for aesthetic quality: it produces striking, art-directed images from text prompts, through Discord and its own web editor."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"ChatGPT Image Generation","d":"OpenAI's image generation built directly into ChatGPT: describe an image in conversation, then refine it with follow-up instructions, including reliable rendered text."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"Ideogram","d":"An image generator known for accurate text rendering and strong graphic-design output: posters, logos, memes and marketing visuals with legible typography."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"FLUX","d":"A family of high-quality image models from the team behind Stable Diffusion, offered through an API and partner platforms rather than one consumer app."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"Adobe Firefly","d":"Adobe's generative AI family, built into Photoshop, Illustrator and Express, and trained on licensed and public-domain content to be commercially safer."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"Canva Magic Studio","d":"Canva's suite of AI design features: text-to-image, background removal, Magic Write copy generation and one-click design resizing."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"Leonardo AI","d":"A creative platform for generating and refining images with fine control: custom model training on your own assets, canvas editing and game/asset production workflows."},{"f":"ai","t":"ai-tools","g":"Image Generation & Design","n":"Recraft","d":"A design-focused image platform strong on vector graphics, icons, illustrations and brand-style control, generating editable SVG as well as raster images."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"Runway","d":"A leading AI video platform: text-to-video and image-to-video generation plus a full editing toolkit for background removal, inpainting and motion control."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"Sora","d":"OpenAI's video generation model and app: it creates short, physically plausible video clips from text or images, with a social app built around remixing creations."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"Veo","d":"Google's video generation model family, available through Gemini and Google's creative tools, producing high-definition clips with increasingly native audio."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"Pika","d":"A friendly AI video generator known for playful effects: its Pikaffects squash, melt, inflate or transform objects in a clip, popular for social content."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"ElevenLabs","d":"The leading AI voice platform: realistic text-to-speech, voice cloning, dubbing and sound effects, used for narration, audiobooks, localisation and accessibility."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"Descript","d":"An audio and video editor that works like a document: edit the transcript and the media edits with it, with AI voices, filler-word removal and studio-quality cleanup."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"HeyGen","d":"An AI avatar platform: presenters generated from a short recording deliver scripts in many languages, used for training, marketing and internal communications."},{"f":"ai","t":"ai-tools","g":"Video & Audio Creation","n":"Suno","d":"An AI music generator that turns text prompts into complete songs with vocals, lyrics and instrumentation."},{"f":"ai","t":"ai-tools","g":"Data & Analysis","n":"Julius AI","d":"An AI data analyst: upload a spreadsheet or connect data, ask questions in plain language, and get charts, summaries and statistical analysis back."},{"f":"ai","t":"ai-tools","g":"Data & Analysis","n":"Rows","d":"A spreadsheet rebuilt with AI and live integrations at its centre: pull data from business tools, enrich and analyse it with AI functions."},{"f":"ai","t":"ai-tools","g":"Data & Analysis","n":"ChatGPT Advanced Data Analysis","d":"ChatGPT's built-in data analysis capability: upload spreadsheets or data files and it writes and runs Python to clean, analyse and chart them, explaining each step."},{"f":"ai","t":"ai-tools","g":"Data & Analysis","n":"Claude with Analysis Tool","d":"Claude's analysis capability: it writes and runs JavaScript in the conversation to compute over uploaded data, producing accurate calculations and charts."},{"f":"ai","t":"ai-tools","g":"Workplace AI Suites","n":"Microsoft 365 Copilot","d":"Microsoft's enterprise AI layer across Word, Excel, PowerPoint, Outlook and Teams: it drafts, summarises and analyses using your organisation's documents."},{"f":"ai","t":"ai-tools","g":"Workplace AI Suites","n":"Gemini for Google Workspace","d":"Google's enterprise AI across Gmail, Docs, Sheets, Slides and Meet: drafting, summarising, meeting notes and the Gemini assistant grounded in your workspace content."},{"f":"ai","t":"ai-tools","g":"Workplace AI Suites","n":"Salesforce Einstein & Agentforce","d":"Salesforce's AI layer for CRM: Einstein provides predictions, scoring and generative drafting inside sales and service workflows."},{"f":"ai","t":"ai-tools","g":"Workplace AI Suites","n":"ServiceNow Now Assist","d":"ServiceNow's generative AI layer for IT and enterprise service workflows: case summarisation, resolution-note generation."},{"f":"ai","t":"ai-tools","g":"Workplace AI Suites","n":"Slack AI","d":"AI inside Slack: channel and thread summaries, catch-up recaps, search answers drawn from your conversations and huddle notes."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Agentic AI","d":"An umbrella term for AI systems built to pursue goals through sequences of decisions and actions, rather than answering a single prompt and stopping."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"AI Agent","d":"A software system that uses a model to decide its next steps, calls tools to act on the world, observes the results and repeats the cycle until its goal is met."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Autonomy","d":"The degree of independence an agent has to choose and execute actions without human approval at each step."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Agent Loop","d":"The repeating cycle at the heart of every agent: perceive the current state, reason about what to do next, take an action through a tool, observe the outcome, and loop."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Goal","d":"The outcome an agent is given to achieve, expressed clearly enough that progress and completion can be judged."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Perception","d":"How an agent takes in the state of its world: reading documents, querying databases, receiving tool results, seeing screenshots or hearing audio."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Action","d":"Anything an agent does that changes something outside itself: calling an API, writing to a database, sending a message, booking, buying or editing a file."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Digital Worker","d":"A business framing for an agent deployed to perform a defined role or set of tasks, like a research assistant, support agent or coding agent."},{"f":"ai","t":"agentic-ai-keywords","g":"Core Concepts","n":"Agent Use Cases","d":"The recurring shapes of work where agents currently deliver value: research and summarisation across sources, coding assistance, customer support resolution."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"Single-Agent System","d":"One agent with a set of tools handling a task end to end."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"Multi-Agent System","d":"A system of several specialised agents that divide work, debate, check each other or operate in parallel under coordination."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"Orchestration","d":"The coordination layer that decides which agent or step runs when, passes context between them, enforces order and handles failures."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"Workflows vs Agents","d":"A workflow follows steps a developer defined in advance; an agent decides its own steps at runtime using a model."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"Supervisor Pattern","d":"A multi-agent design where one supervisor agent plans the work, delegates subtasks to worker agents, reviews their outputs and assembles the final result."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"Handoff","d":"The moment control and context pass from one agent (or an agent and a human) to another."},{"f":"ai","t":"agentic-ai-keywords","g":"Agent Architecture","n":"State","d":"The recorded progress of an agent's work: what has been done, what is known, what is pending."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"Reasoning","d":"The model's process of working through a problem: weighing options, checking constraints and choosing a next step."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"Planning","d":"An agent's ability to look ahead: break a goal into steps, order them, anticipate dependencies and revise when reality changes."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"Task Decomposition","d":"Breaking a large goal into smaller subtasks that can be executed, checked and retried independently."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"Chain-of-Thought","d":"A technique where the model works through intermediate steps in text before answering or acting, which improves performance on multi-step problems."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"ReAct","d":"A foundational agent pattern (Reason + Act) where the model alternates between short reasoning steps and tool actions, using each observation to decide the next move."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"Reflection","d":"An agent reviewing its own output or plan, critiquing it against criteria, and revising before proceeding."},{"f":"ai","t":"agentic-ai-keywords","g":"Reasoning & Planning","n":"Error Recovery","d":"How an agent responds when a tool fails, data is missing or an action produces an unexpected result: retry with changes, choose an alternative path, ask for help."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"Tool Use / Function Calling","d":"The mechanism by which a model requests that external code run: it emits a structured call (a function name and arguments), the system executes it."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"Tool","d":"A function an agent can invoke: search, read a file, query a database, send an email, run code, create a ticket."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"Tool Design","d":"The craft of building tools agents can use reliably: narrow scope, clear names, unambiguous descriptions, structured inputs."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"MCP","d":"An open protocol that standardises how AI systems connect to tools, data sources and services."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"A2A","d":"An open protocol for agents built by different vendors to discover each other, delegate tasks and exchange results."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"Computer Use","d":"An agent capability to operate software through its ordinary interface: seeing a screen, moving a pointer, clicking and typing, the way a person would."},{"f":"ai","t":"agentic-ai-keywords","g":"Tools & Actions","n":"Browser Agent","d":"An agent that works through a web browser: navigating sites, filling forms, extracting information and completing transactions."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Context Engineering","d":"The discipline of deciding what information an agent sees at each step: instructions, history, retrieved documents, tool results and state."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Context Window","d":"The maximum amount of text (measured in tokens) a model can consider at once: its working memory for a single step."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Short-Term Memory","d":"The agent's memory within a task or session: the conversation, intermediate results and current plan held in the context window or session state."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Long-Term Memory","d":"Information an agent persists across sessions: user preferences, facts learned, past outcomes and organisational knowledge."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Episodic Memory","d":"Memory of specific past events and interactions: what happened, in what order, with what outcome."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Semantic Memory","d":"An agent's store of general facts and knowledge about its domain, organisation and users, abstracted from individual events: policies, product facts, definitions."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Vector Memory","d":"A storage method where text is converted into embeddings (numeric representations of meaning) and stored in a vector database."},{"f":"ai","t":"agentic-ai-keywords","g":"Context & Memory","n":"Context Management","d":"The operational side of context engineering: summarising history before it overflows, pruning stale tool results, caching stable material and deciding what to drop."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Guardrails","d":"Rules and mechanisms that constrain an agent's behaviour: input and output filters, action allow-lists, spending limits."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Sandbox","d":"An isolated environment where an agent can run code, browse or use tools without touching production systems, real credentials or live data."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Least-Privilege Access","d":"Granting an agent only the permissions each task requires, for only as long as required: read before write, one system before many."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Human-in-the-Loop","d":"A design where a person approves, edits or rejects an agent's proposed action before it executes, at least for defined categories of action."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Human-on-the-Loop","d":"A supervisory model where the agent acts autonomously but a human monitors live activity with the ability to pause, intervene or roll back."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Prompt Injection","d":"An attack where malicious instructions hidden in content an agent reads (a web page, email."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Kill Switch","d":"A tested mechanism to halt an agent or a whole agent system immediately: revoking its credentials, pausing its queues or disabling its tools."},{"f":"ai","t":"agentic-ai-keywords","g":"Safety & Control","n":"Runaway Loops","d":"A failure mode where an agent cycles without progressing: retrying the same failing action, calling itself or another agent endlessly, or refining forever."},{"f":"ai","t":"agentic-ai-keywords","g":"Evaluation & Observability","n":"Agent Evals","d":"Systematic tests of an agent against representative tasks with scored outcomes, run before deployment and after every significant change."},{"f":"ai","t":"agentic-ai-keywords","g":"Evaluation & Observability","n":"Trajectory Evaluation","d":"Judging an agent not only by its final answer but by the path it took: the steps chosen, tools called, detours, recoveries and near-misses."},{"f":"ai","t":"agentic-ai-keywords","g":"Evaluation & Observability","n":"LLM-as-Judge","d":"Using a language model to grade agent outputs or trajectories against a rubric, enabling evaluation at a scale humans cannot match."},{"f":"ai","t":"agentic-ai-keywords","g":"Evaluation & Observability","n":"Tracing & Observability","d":"Recording every step of an agent's work: prompts, context, model calls, tool calls, results, costs and timings, in a form engineers and auditors can replay."},{"f":"ai","t":"agentic-ai-keywords","g":"Evaluation & Observability","n":"Agent Benchmarks","d":"Public test suites that measure agent capability on standardised tasks, such as software engineering, web navigation or office work."},{"f":"ai","t":"agentic-ai-keywords","g":"Evaluation & Observability","n":"Reliability","d":"How consistently an agent completes tasks correctly across many runs, including unusual inputs and partial failures."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"AgentOps","d":"The operational discipline of running agents in production: deployment, monitoring, cost control, incident response, version management and continuous evaluation."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"Agent Frameworks","d":"Software libraries and platforms that provide the building blocks for agents: loops, tool interfaces, memory, orchestration and integrations."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"Coding Agents","d":"Agents specialised in software work: writing and editing code, running tests."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"Voice Agents","d":"Agents that converse by phone or voice in real time, combining speech recognition, a language model, tool actions and speech synthesis."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"Token Budget","d":"A cap on how many tokens (roughly, units of text) an agent may consume on a task, set in advance."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"Cost per Task","d":"The full unit cost of an agent completing one piece of work: model tokens, tool and API charges, infrastructure."},{"f":"ai","t":"agentic-ai-keywords","g":"Deployment & Operations","n":"Scaling Agents","d":"Running many agent instances in parallel across teams or workloads, with the queueing, rate limits, credential management and cost governance that requires."},{"f":"ai","t":"agentic-ai-keywords","g":"Business & Value","n":"ROI of Agents","d":"The return calculation for agent deployments: hours and costs removed, quality and speed gained, against build, licence, token, supervision and incident costs."},{"f":"ai","t":"agentic-ai-keywords","g":"Business & Value","n":"Build vs Buy Agents","d":"The decision between assembling agents on frameworks and your own infrastructure, buying packaged agents from platform vendors, or a hybrid."},{"f":"ai","t":"agentic-ai-keywords","g":"Business & Value","n":"Agent Governance","d":"The organisational system for agents: an inventory of what agents exist, who owns them, what they may access and do, how they are evaluated, and how they are retired."},{"f":"ai","t":"agentic-ai-keywords","g":"Business & Value","n":"Agent Readiness","d":"An organisation's preparedness to deploy agents well: clean and accessible data, API-ready systems, documented processes."},{"f":"ai","t":"agentic-ai-keywords","g":"Business & Value","n":"Agent Strategy","d":"A deliberate plan for where agents will and will not be used across the organisation, sequenced by value, verifiability and risk."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"LangChain","d":"One of the earliest and largest open-source frameworks for building LLM applications, offering abstractions for prompts, models, retrievers, tools and agent loops."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"LangGraph","d":"LangChain's graph-based framework for stateful, controllable agents: workflows are built as nodes and edges with explicit state, checkpoints."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"CrewAI","d":"A Python framework for orchestrating role-based multi-agent crews, where agents receive roles, goals and tools and collaborate through defined processes."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"Microsoft AutoGen","d":"Microsoft Research's framework for conversational multi-agent systems, where agents talk to each other and to humans in order to solve tasks."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"Semantic Kernel","d":"Microsoft's software development kit for bringing LLMs and agents into enterprise applications, offering planners, plugins and connectors in .NET, Python and Java."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"LlamaIndex","d":"A framework centred on the data side of LLM applications: ingestion, indexing and retrieval for RAG, extended into agent and workflow patterns."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"OpenAI Agents SDK","d":"OpenAI's lightweight framework for building agents on its models, providing agents, tools, handoffs between agents, guardrails and built-in tracing."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"Claude Agent SDK","d":"Anthropic's SDK for building agents on Claude, sharing harness ideas with Claude Code: structured tool use, context management and subagents."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"Google ADK","d":"Agent Development Kit: Google's open-source framework for building and deploying agents, designed to work with Google's models and Vertex AI while also supporting others."},{"f":"ai","t":"agentic-ai-tools","g":"Agent Frameworks (Code)","n":"Pydantic AI","d":"A Python agent framework from the Pydantic team that brings type safety, structured outputs and validation to agent development."},{"f":"ai","t":"agentic-ai-tools","g":"Low-Code & Workflow Builders","n":"Langflow","d":"A visual, drag-and-drop builder for LangChain-based flows and agents, letting users wire components on a canvas and export them as deployable APIs."},{"f":"ai","t":"agentic-ai-tools","g":"Low-Code & Workflow Builders","n":"Flowise","d":"An open-source visual builder for LLM flows and agents, similar in spirit to Langflow."},{"f":"ai","t":"agentic-ai-tools","g":"Low-Code & Workflow Builders","n":"n8n","d":"A workflow automation platform with strong AI nodes that let users place agent steps inside broader automations spanning hundreds of business apps."},{"f":"ai","t":"agentic-ai-tools","g":"Low-Code & Workflow Builders","n":"Dust","d":"A platform for building company-internal AI agents and assistants connected to internal knowledge and tools, aimed at enterprise teams rather than developers first."},{"f":"ai","t":"agentic-ai-tools","g":"Low-Code & Workflow Builders","n":"Relevance AI","d":"A no-code and low-code platform for building an AI workforce of agents that automate business processes such as research, sales tasks and support operations."},{"f":"ai","t":"agentic-ai-tools","g":"Low-Code & Workflow Builders","n":"Lindy","d":"A platform for creating AI employees and agents that handle tasks such as email triage, meeting preparation, lead research and CRM updates."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"GitHub Copilot","d":"Microsoft's AI coding assistant, which began as autocomplete inside the editor and has grown into agent modes that edit multiple files."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"Cursor","d":"An AI-first code editor, built as a fork of VS Code, designed around agents that edit codebases, run commands and reason over repository context."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"Claude Code","d":"Anthropic's coding agent that works from the terminal and inside IDEs, reading an entire codebase, editing files."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"OpenAI Codex","d":"OpenAI's coding agent line: cloud agents that work on repositories in parallel sandboxes, alongside CLI and IDE forms, powered by code-specialised GPT models."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"Devin Desktop (formerly Windsurf)","d":"An AI code editor built around its Devin Local agent, offering agentic editing and codebase awareness for individuals and enterprise teams."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"Devin","d":"Cognition's autonomous software-engineering agent, positioned as an AI engineer that takes tickets end to end inside a cloud workspace, planning work."},{"f":"ai","t":"agentic-ai-tools","g":"Coding Agents","n":"Replit Agent","d":"Replit's agent that builds working applications from natural-language descriptions inside its browser-based development and hosting platform."},{"f":"ai","t":"agentic-ai-tools","g":"Computer & Browser Agents","n":"Anthropic Computer Use","d":"A capability that lets Claude perceive screenshots and control a computer's mouse and keyboard, completing tasks inside real software interfaces."},{"f":"ai","t":"agentic-ai-tools","g":"Computer & Browser Agents","n":"ChatGPT agent (formerly OpenAI Operator)","d":"OpenAI's computer-using agent that browses and acts on websites, handling tasks such as bookings, ordering and form-filling in its own browser."},{"f":"ai","t":"agentic-ai-tools","g":"Computer & Browser Agents","n":"Browser Use","d":"An open-source library that connects LLM agents to a real browser so they can navigate websites, fill forms and extract data."},{"f":"ai","t":"agentic-ai-tools","g":"Computer & Browser Agents","n":"Google Project Mariner","d":"Google DeepMind's research prototype for browser agents that can understand and act across web pages to complete tasks such as shopping and research."},{"f":"ai","t":"agentic-ai-tools","g":"Voice Agents","n":"ElevenLabs","d":"A voice AI company known for highly natural text-to-speech and voice cloning, extended into a conversational agents platform for phone and web voice agents."},{"f":"ai","t":"agentic-ai-tools","g":"Voice Agents","n":"Vapi","d":"A developer platform for building voice agents that handle live phone and web calls with low latency, orchestrating speech-to-text."},{"f":"ai","t":"agentic-ai-tools","g":"Voice Agents","n":"Retell AI","d":"A platform for building and deploying AI phone agents for support, sales and operations, with testing tools."},{"f":"ai","t":"agentic-ai-tools","g":"Voice Agents","n":"LiveKit","d":"An open-source infrastructure platform, built on WebRTC, for real-time voice and video, with an agents framework for building voice agents on top of it."},{"f":"ai","t":"agentic-ai-tools","g":"Memory & Retrieval","n":"Pinecone","d":"A managed vector database for storing and searching embeddings, forming the retrieval backbone of many RAG pipelines and agent memory systems."},{"f":"ai","t":"agentic-ai-tools","g":"Memory & Retrieval","n":"Weaviate","d":"An open-source vector database offering hybrid search that combines vectors with keyword search, plus built-in options for generating embeddings."},{"f":"ai","t":"agentic-ai-tools","g":"Memory & Retrieval","n":"Chroma","d":"A lightweight open-source vector database designed for developer simplicity, making it a common first choice for prototypes, experiments and local agent memory."},{"f":"ai","t":"agentic-ai-tools","g":"Memory & Retrieval","n":"Mem0","d":"A memory layer for AI agents and applications that extracts, stores and retrieves persistent memories about users and past interactions."},{"f":"ai","t":"agentic-ai-tools","g":"Memory & Retrieval","n":"Zep","d":"A memory and context platform for agents built around a temporal knowledge graph, its Graphiti engine."},{"f":"ai","t":"agentic-ai-tools","g":"Evaluation & Observability","n":"LangSmith","d":"LangChain's platform for tracing, evaluating and monitoring LLM and agent applications, bringing run traces, datasets."},{"f":"ai","t":"agentic-ai-tools","g":"Evaluation & Observability","n":"Langfuse","d":"An open-source LLM engineering platform covering tracing, prompt management, evaluations and product analytics for AI applications."},{"f":"ai","t":"agentic-ai-tools","g":"Evaluation & Observability","n":"Arize Phoenix","d":"An open-source observability and evaluation tool for LLM systems, strong at tracing, retrieval debugging and embedding analysis."},{"f":"ai","t":"agentic-ai-tools","g":"Evaluation & Observability","n":"Braintrust","d":"A commercial platform for evaluating and steadily improving AI products: evaluations, datasets, prompt iteration, production logging and regression testing."},{"f":"ai","t":"agentic-ai-tools","g":"Evaluation & Observability","n":"Promptfoo","d":"An open-source command-line tool for testing and red-teaming prompts, RAG pipelines and agents, running evaluations in continuous integration much like unit tests."},{"f":"ai","t":"agentic-ai-tools","g":"Evaluation & Observability","n":"AgentOps","d":"An observability platform focused specifically on agents rather than generic LLM calls, offering session replays, step-by-step traces."},{"f":"ai","t":"agentic-ai-tools","g":"Enterprise Agent Platforms","n":"Microsoft Copilot Studio","d":"Microsoft's platform for building and governing agents inside the Microsoft 365 and Power Platform ecosystem."},{"f":"ai","t":"agentic-ai-tools","g":"Enterprise Agent Platforms","n":"Salesforce Agentforce","d":"Salesforce's platform for autonomous agents operating inside CRM workflows: service, sales and marketing agents grounded in Salesforce data and processes."},{"f":"ai","t":"agentic-ai-tools","g":"Enterprise Agent Platforms","n":"ServiceNow AI Agents","d":"ServiceNow's agentic layer inside its workflow platform, orchestrating AI agents across IT service."},{"f":"ai","t":"agentic-ai-tools","g":"Enterprise Agent Platforms","n":"Amazon Bedrock Agents","d":"AWS's managed service for building agents that plan multi-step tasks, call APIs through defined action groups and retrieve from knowledge bases."},{"f":"ai","t":"agentic-ai-tools","g":"Enterprise Agent Platforms","n":"Google Agent Builder (Gemini Enterprise Agent Platform)","d":"Google Cloud's suite for building, deploying and managing agents, combining the Agent Engine managed runtime with ADK support."},{"f":"ai","t":"agentic-ai-tools","g":"Enterprise Agent Platforms","n":"IBM watsonx Orchestrate","d":"IBM's platform for building and managing agents and assistants across enterprise workflows, offering prebuilt agents for areas such as HR."},{"f":"ai","t":"agentic-ai-tools","g":"Automation Platforms with Agents","n":"Zapier","d":"The veteran no-code automation platform connecting thousands of business applications."},{"f":"ai","t":"agentic-ai-tools","g":"Automation Platforms with Agents","n":"Make","d":"A visual automation platform, formerly Integromat, for building multi-step scenarios across applications and APIs."},{"f":"ai","t":"agentic-ai-tools","g":"Automation Platforms with Agents","n":"UiPath","d":"The robotic process automation leader extending into agentic automation, combining software robots with AI agents that operate across user interfaces."},{"f":"ai","t":"agentic-ai-tools","g":"Automation Platforms with Agents","n":"Workato","d":"An enterprise integration and automation platform (iPaaS) with agent features delivered through its 'genies' and agent tooling."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Cloud Computing","d":"Delivering computing \u2014 servers, storage, databases, networking and software \u2014 over the internet from a provider's data centres."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Public Cloud","d":"Cloud services offered over the public internet by providers such as AWS, Microsoft Azure and Google Cloud."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Private Cloud","d":"Cloud infrastructure operated for a single organisation, either in its own data centre or hosted by a provider."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Hybrid Cloud","d":"An environment combining private infrastructure (or on-premises systems) with public cloud, connected so workloads and data can move or cooperate between them."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Multi-Cloud","d":"Using services from more than one public cloud provider, deliberately \u2014 for example analytics on one provider and core systems on another."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Region","d":"A geographic area where a cloud provider operates one or more data centres, such as a region centred on Mumbai, Frankfurt or Virginia."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Availability Zone","d":"One or more physically separate data centres within a region, each with independent power, cooling and networking, connected by fast low-latency links."},{"f":"cloud","t":"cloud-devops","g":"Cloud Foundations","n":"Edge Computing","d":"Processing data physically close to where it is created \u2014 in factories, retail stores."},{"f":"cloud","t":"cloud-devops","g":"Service Models","n":"IaaS","d":"Infrastructure as a Service: the provider supplies raw computing building blocks \u2014 virtual machines, storage and networks \u2014 and you manage everything above them."},{"f":"cloud","t":"cloud-devops","g":"Service Models","n":"PaaS","d":"Platform as a Service: the provider manages the infrastructure and the runtime platform \u2014 operating system, patching."},{"f":"cloud","t":"cloud-devops","g":"Service Models","n":"SaaS","d":"Software as a Service: a complete application delivered over the internet on subscription, such as email, CRM or HR systems."},{"f":"cloud","t":"cloud-devops","g":"Service Models","n":"Serverless","d":"A model where you deploy code (functions) or services without provisioning or managing servers at all; the provider runs, scales and bills them per use."},{"f":"cloud","t":"cloud-devops","g":"Service Models","n":"Managed Services","d":"Provider-operated versions of common components \u2014 databases, message queues, Kubernetes, search \u2014 where the provider handles patching, backups."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Virtual Machine","d":"A software emulation of a physical computer, running its own full operating system on shared hardware through a hypervisor."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Container","d":"A lightweight, standard package containing an application and everything it needs to run, sharing the host operating system kernel instead of carrying its own."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Docker","d":"The tooling that made containers mainstream: a format for packaging applications into container images and an engine for running them."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Kubernetes","d":"The open-source platform (originally from Google) that orchestrates containers at scale: it schedules them across machines, restarts failures."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Pod","d":"The smallest deployable unit in Kubernetes: one or more containers that share networking and storage and are always scheduled together on the same machine."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Microservices","d":"An architecture style that splits an application into small, independently deployable services, each owning one business capability and communicating over a network."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Monolith","d":"An application built and deployed as a single unified unit, with all functions running in one process and usually sharing one database."},{"f":"cloud","t":"cloud-devops","g":"Compute & Containers","n":"Auto Scaling","d":"Automatically adding or removing computing capacity in response to demand signals such as CPU use, request queues or schedules."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"Object Storage","d":"Storage that manages data as discrete objects \u2014 a file plus metadata plus a unique address \u2014 accessed over HTTP APIs, exemplified by Amazon S3."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"Block Storage","d":"Storage presented to a server as a raw virtual disk, divided into fixed-size blocks, used for operating systems and databases that need fast, low-latency access."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"SQL Database","d":"A relational database (PostgreSQL, MySQL, SQL Server and similar) that stores data in structured tables with defined relationships and guarantees transactions through."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"NoSQL Database","d":"A family of non-relational databases \u2014 document, key-value, wide-column and graph stores \u2014 designed for flexible data models and very large scale."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"Cache","d":"A fast, usually in-memory layer (such as Redis or Memcached) holding copies of frequently requested data so applications stop asking the database the same questions."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"CDN","d":"Content Delivery Network: a globally distributed set of servers that caches your content \u2014 images, video, scripts."},{"f":"cloud","t":"cloud-devops","g":"Storage & Data","n":"Backup","d":"Copies of data (and the system configuration needed to use it) kept separately so service can be restored after failure, corruption, deletion or ransomware."},{"f":"cloud","t":"cloud-devops","g":"Networking","n":"VPC","d":"Virtual Private Cloud: your own isolated section of a public cloud, with private IP ranges and network rules that you define, inside which your resources run."},{"f":"cloud","t":"cloud-devops","g":"Networking","n":"Subnet","d":"A subdivision of a network (such as a VPC) with its own IP address range, typically used to separate tiers: public subnets hold load balancers."},{"f":"cloud","t":"cloud-devops","g":"Networking","n":"Load Balancer","d":"A service that distributes incoming traffic across multiple healthy copies of an application."},{"f":"cloud","t":"cloud-devops","g":"Networking","n":"API Gateway","d":"A managed entry point for APIs that handles authentication, rate limiting, request routing and logging before traffic reaches backend services."},{"f":"cloud","t":"cloud-devops","g":"Networking","n":"DNS","d":"The Domain Name System: the internet's directory, translating names people remember (such as your website address) into the IP addresses machines use."},{"f":"cloud","t":"cloud-devops","g":"Networking","n":"VPN","d":"Virtual Private Network: an encrypted tunnel over a public network that connects offices, data centres or individual users privately to a cloud network."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"DevOps","d":"A working culture and set of practices where the teams who build software share responsibility for running it, joined by automation across building."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"CI/CD","d":"Continuous Integration and Continuous Delivery (or Deployment): automatically building, testing and packaging every code change (CI)."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"Pipeline","d":"The automated sequence a code change travels: build, unit tests, security scans, staging deployment, further checks, and release."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"GitOps","d":"Operating infrastructure and applications by declaring their desired state in a Git repository and letting automation continuously converge the live environment to match."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"Infrastructure as Code","d":"Defining infrastructure \u2014 servers, networks, databases, permissions \u2014 in machine-readable files that are versioned, reviewed and applied by tools."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"Terraform","d":"The most widely used infrastructure-as-code tool (by HashiCorp), which provisions resources across AWS, Azure."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"Configuration Management","d":"Tools (such as Ansible, Chef or Puppet) that define and enforce the desired state of servers themselves \u2014 installed packages, settings."},{"f":"cloud","t":"cloud-devops","g":"DevOps & Delivery","n":"Artifact Repository","d":"A controlled store for the built outputs of your pipeline \u2014 container images, packages and libraries \u2014 with versions, metadata and security scan results."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"SRE","d":"An engineering discipline (originated at Google) that applies software engineering to operations."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Observability","d":"The ability to understand what a system is doing internally from the evidence it emits \u2014 metrics, logs and traces \u2014 including questions nobody predicted in advance."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Monitoring","d":"Continuously collecting and alerting on predefined indicators of system health \u2014 CPU, memory, error rates, queue lengths \u2014 against known thresholds."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Logging","d":"Recording timestamped events from applications and infrastructure into a searchable central store."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Tracing","d":"Recording the path of a single request as it travels through many services, with the time spent in each."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"SLI","d":"Service Level Indicator: a precise quantitative measure of some aspect of service quality, always expressed as a ratio of good outcomes to total outcomes."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"SLO","d":"Service Level Objective: the internal target set for an SLI over a period, such as 99.9% of requests succeeding over 30 days."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"SLA","d":"Service Level Agreement: the external, contractual commitment made to customers about service levels."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Error Budget","d":"The amount of unreliability an SLO permits over a period: if the target is 99.9% availability, the budget is the remaining 0.1% of requests that may fail."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Incident Management","d":"The organised process for responding to service failures: declaring an incident, assigning a commander, coordinating responders, communicating status."},{"f":"cloud","t":"cloud-devops","g":"Reliability & Observability","n":"Blameless Postmortem","d":"A written review after an incident that reconstructs the timeline, identifies systemic contributing factors."},{"f":"cloud","t":"cloud-devops","g":"Cloud Security & Governance","n":"IAM","d":"Identity and Access Management: the controls deciding who (person or machine) can do what to which cloud resources, through accounts, roles and policies."},{"f":"cloud","t":"cloud-devops","g":"Cloud Security & Governance","n":"CSPM","d":"Cloud Security Posture Management: tools that continuously scan cloud accounts for misconfiguration \u2014 public storage, unencrypted databases, excessive permissions."},{"f":"cloud","t":"cloud-devops","g":"Cloud Security & Governance","n":"Landing Zone","d":"A pre-configured, secure foundation environment into which cloud workloads are deployed: account structure, network design, logging."},{"f":"cloud","t":"cloud-devops","g":"Cloud Security & Governance","n":"Well-Architected Framework","d":"The major providers' published design frameworks (AWS, Azure and Google each maintain one) assessing systems against pillars such as operational excellence, security."},{"f":"cloud","t":"cloud-devops","g":"Cloud Security & Governance","n":"Cloud Governance","d":"The policies, guardrails and accountabilities that keep a growing cloud estate secure, compliant and affordable: who may create resources, where data may live."},{"f":"cloud","t":"cloud-devops","g":"Cloud Security & Governance","n":"Shared Responsibility Model","d":"The division of security duties between cloud provider and customer: the provider secures the cloud itself (facilities, hardware, core network)."},{"f":"cloud","t":"cloud-devops","g":"Resilience","n":"High Availability","d":"Designing a system to remain operational despite component failures, by removing single points of failure and automating recovery."},{"f":"cloud","t":"cloud-devops","g":"Resilience","n":"Disaster Recovery","d":"The plans, architecture and rehearsed procedures for restoring services after a major loss \u2014 a region failure, destructive attack or catastrophic error."},{"f":"cloud","t":"cloud-devops","g":"Resilience","n":"RTO","d":"Recovery Time Objective: the maximum acceptable time between a disaster striking and the service being usable again."},{"f":"cloud","t":"cloud-devops","g":"Resilience","n":"RPO","d":"Recovery Point Objective: the maximum acceptable amount of data loss, expressed as time \u2014 how far back to the last good copy you may have to go when restoring."},{"f":"cloud","t":"cloud-devops","g":"Resilience","n":"Chaos Engineering","d":"Deliberately injecting controlled failures into systems \u2014 killing instances, adding latency."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"FinOps","d":"The operating discipline that brings financial accountability to cloud spending: engineering, finance and business teams jointly owning cloud costs."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Cloud Cost Optimisation","d":"The ongoing practice of matching cloud spend to actual need: rightsizing over-provisioned resources, deleting the unused."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Reserved Instances","d":"A commitment to use a defined amount of compute capacity for a one- or three-year term in exchange for a significantly lower hourly price than pay-as-you-go (on-demand)."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Spot Instances","d":"Spare provider capacity sold at deep discounts because the provider may reclaim it at short notice when paying customers need it."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Cloud Migration","d":"Moving applications, data and operations from on-premises (or another cloud) to a cloud platform, including the surrounding changes to operating model."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Lift and Shift","d":"Migrating systems to the cloud with minimal change \u2014 the same software, moved onto cloud virtual machines (also called rehosting)."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Replatforming","d":"Migrating with targeted, limited changes to exploit cloud services without redesigning the application \u2014 for example moving a self-managed database to a managed database."},{"f":"cloud","t":"cloud-devops","g":"Cost & Strategy","n":"Refactoring","d":"Redesigning and substantially rewriting an application to be cloud-native \u2014 decomposed into services, using managed and serverless components."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"EC2","d":"Virtual servers in the cloud and the original AWS compute service: you choose the processor, memory and storage size, install your own operating system and software."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"Auto Scaling","d":"A capability that watches demand on your applications and automatically adds EC2 instances when traffic rises and removes them when it falls."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"Lambda","d":"A compute service that runs small pieces of code in response to events \u2014 a file arriving, a button clicked, a message queued \u2014 with no server to provision or patch."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"ECS","d":"AWS's own service for running software containers \u2014 standardised packages of an application and everything it needs \u2014 across a cluster of machines."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"EKS","d":"A managed Kubernetes service: AWS runs the Kubernetes control plane that schedules and heals containers."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"Fargate","d":"A serverless way to run containers on ECS or EKS: you specify the CPU and memory each task needs and AWS runs it without you managing the underlying instances."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"Lightsail","d":"A simplified, fixed-price package of compute, storage and networking aimed at small websites."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"Graviton Processors","d":"AWS-designed processors based on Arm architecture, offered across EC2, databases and many managed services."},{"f":"cloud","t":"aws-leaders","g":"Compute","n":"Elastic Beanstalk","d":"A simplified deployment service for web applications: you upload code in common languages such as Java, .NET, Python or Node.js, and Beanstalk provisions the servers."},{"f":"cloud","t":"aws-leaders","g":"Storage","n":"S3","d":"Object storage: files of any size stored as objects in containers called buckets, reached over the internet or privately inside AWS."},{"f":"cloud","t":"aws-leaders","g":"Storage","n":"EBS","d":"Block storage volumes that attach to EC2 instances like virtual hard drives, holding operating systems."},{"f":"cloud","t":"aws-leaders","g":"Storage","n":"EFS","d":"A shared file system that many servers can read and write at the same time, using the standard NFS protocol familiar from on-premises storage."},{"f":"cloud","t":"aws-leaders","g":"Storage","n":"S3 Glacier","d":"The very low-cost archive tiers of S3, designed for data that must be kept for years \u2014 backups, compliance records, media archives \u2014 but is rarely read."},{"f":"cloud","t":"aws-leaders","g":"Storage","n":"Storage Gateway","d":"A hybrid service that connects your on-premises systems to S3 and other AWS storage, presenting cloud storage as a local file share, disk or tape library."},{"f":"cloud","t":"aws-leaders","g":"Storage","n":"AWS Backup","d":"A central service for defining and automating backup policies across AWS services \u2014 EC2, databases."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"RDS","d":"Managed traditional databases \u2014 MySQL, PostgreSQL, Oracle, SQL Server and MariaDB \u2014 where AWS handles installation, patching."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"Aurora","d":"AWS's own re-engineered relational database, compatible with MySQL and PostgreSQL applications but rebuilt for the cloud with storage that grows automatically and."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"DynamoDB","d":"AWS's fully managed key-value and document database, built for very large scale and predictably fast responses \u2014 shopping carts, user profiles, session data, game state."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"Redshift","d":"AWS's data warehouse service for large-scale analytics: it stores data in columns and runs heavy SQL queries across terabytes to petabytes for dashboards and business."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"ElastiCache","d":"A managed in-memory cache using Redis or Memcached technology, sitting in front of your databases to serve frequently read data in under a millisecond."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"Athena","d":"A serverless analytics service that runs standard SQL queries directly against data sitting in S3 \u2014 no warehouse to load, no servers to run."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"EMR","d":"A managed big-data platform for processing enormous datasets with open-source frameworks such as Apache Spark and Hadoop \u2014 log processing, machine-learning preparation."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"Kinesis","d":"A family of services for collecting and processing streaming data in real time \u2014 clickstreams, sensor readings, application logs."},{"f":"cloud","t":"aws-leaders","g":"Databases & Analytics","n":"OpenSearch Service","d":"Managed search and log analytics based on the open-source OpenSearch project (forked from Elasticsearch): full-text search for applications."},{"f":"cloud","t":"aws-leaders","g":"Networking & Content Delivery","n":"VPC","d":"Your private, isolated section of the AWS network: you define the address ranges, subnets, routing and the rules for what can enter or leave."},{"f":"cloud","t":"aws-leaders","g":"Networking & Content Delivery","n":"Route 53","d":"AWS's Domain Name System service: it registers domain names and translates names like yourcompany.com into the servers that answer them."},{"f":"cloud","t":"aws-leaders","g":"Networking & Content Delivery","n":"CloudFront","d":"AWS's content delivery network: it copies your website's static content."},{"f":"cloud","t":"aws-leaders","g":"Networking & Content Delivery","n":"ELB","d":"Managed load balancers that spread incoming traffic across your servers or containers, detect failures and stop sending users to unhealthy copies."},{"f":"cloud","t":"aws-leaders","g":"Networking & Content Delivery","n":"Direct Connect","d":"A private, dedicated network connection from your data centre or office into AWS, bypassing the public internet for predictable speed."},{"f":"cloud","t":"aws-leaders","g":"Networking & Content Delivery","n":"API Gateway","d":"A managed front door for your application programming interfaces: it receives API calls from apps, partners and other systems, checks who is calling, throttles abuse."},{"f":"cloud","t":"aws-leaders","g":"Security & Identity","n":"IAM","d":"The service that decides who can do what in AWS: every person, application and service gets an identity with permissions, and every action is checked against them."},{"f":"cloud","t":"aws-leaders","g":"Security & Identity","n":"AWS Organizations","d":"The service for governing many AWS accounts as one enterprise: you create a structure of accounts \u2014 for departments."},{"f":"cloud","t":"aws-leaders","g":"Security & Identity","n":"KMS","d":"The service that creates and controls the encryption keys protecting your data across AWS: databases, storage and backups encrypt through keys you govern."},{"f":"cloud","t":"aws-leaders","g":"Security & Identity","n":"GuardDuty","d":"A threat-detection service that continuously analyses AWS account activity, network flows and data-access patterns for signs of compromise \u2014 stolen credentials."},{"f":"cloud","t":"aws-leaders","g":"Security & Identity","n":"CloudTrail","d":"The audit log of AWS itself: it records who did what, when, from where, across your accounts \u2014 every console click and API call."},{"f":"cloud","t":"aws-leaders","g":"Security & Identity","n":"WAF","d":"A firewall for web applications that filters incoming HTTP requests before they reach your sites and APIs."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"Bedrock","d":"AWS's managed service for generative AI: one API giving access to foundation models from several providers \u2014 including Anthropic's Claude, Meta's Llama."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"SageMaker","d":"AWS's platform for data scientists and ML engineers to build, train and deploy machine-learning models at scale."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"Amazon Q","d":"AWS's generative-AI assistant family for work: Amazon Q Business answers questions over company documents and systems for employees."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"Rekognition","d":"A managed image and video analysis service: it detects objects, faces, text and inappropriate content, and supports uses such as identity verification."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"Comprehend","d":"A natural-language processing service that extracts meaning from text: sentiment, topics, key phrases, entities such as people and organisations."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"Bedrock AgentCore & Agents","d":"AWS's tooling for building AI agents \u2014 systems that reason over a request, call your APIs and data, and complete multi-step tasks."},{"f":"cloud","t":"aws-leaders","g":"AI & Machine Learning","n":"Textract","d":"A managed document-understanding service that extracts text, tables and form fields from scanned documents and PDFs \u2014 invoices, applications, ID documents."},{"f":"cloud","t":"aws-leaders","g":"Developer, Integration & DevOps","n":"SQS","d":"A managed message queue: components of a system leave messages for each other instead of calling directly."},{"f":"cloud","t":"aws-leaders","g":"Developer, Integration & DevOps","n":"SNS","d":"A publish-and-subscribe messaging service: one event is fanned out to many subscribers at once \u2014 other systems, queues, email, SMS or mobile push notifications."},{"f":"cloud","t":"aws-leaders","g":"Developer, Integration & DevOps","n":"EventBridge","d":"A serverless event bus that routes events between AWS services, your applications and third-party software such as CRM and support tools, using rules you define."},{"f":"cloud","t":"aws-leaders","g":"Developer, Integration & DevOps","n":"Step Functions","d":"A visual workflow service that stitches Lambda functions and other services into multi-step processes with branching."},{"f":"cloud","t":"aws-leaders","g":"Developer, Integration & DevOps","n":"CloudFormation","d":"AWS's infrastructure-as-code service: the entire environment \u2014 networks, servers, databases, permissions \u2014 is described in template files and deployed."},{"f":"cloud","t":"aws-leaders","g":"Developer, Integration & DevOps","n":"CodePipeline","d":"A continuous-delivery service that automates the path from a developer committing code to that code being tested, approved and deployed, in a visible pipeline."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"CloudWatch","d":"The monitoring and observability service of AWS: it collects metrics, logs and events from virtually every service, raises alarms when thresholds break."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"Cost Explorer","d":"AWS's built-in cost analysis tool: it breaks your bill down by service, account, team tag and time, forecasts next month's spend, and shows where money actually went."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"Savings Plans","d":"A discount programme: commit to a steady level of compute usage (measured in dollars per hour) for one or three years."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"Reserved Instances & Capacity","d":"The original AWS discount mechanism: reserve specific instance capacity in a region for one or three years in exchange for a lower hourly rate."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"Trusted Advisor","d":"An automated advisory service that scans your estate against AWS best practices across cost, security, performance, fault tolerance and service limits."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"Well-Architected Framework","d":"AWS's codified set of design best practices, organised in six pillars \u2014 operational excellence, security, reliability, performance efficiency."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"AWS Shared Responsibility Model","d":"The division of security duties between AWS and you: AWS secures the cloud itself \u2014 facilities, hardware, the core network \u2014 while you secure what you put in it."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"Migration Hub","d":"AWS's central tracking service for cloud migrations: it inventories servers and applications, groups dependencies."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"AWS Support Plans","d":"The tiered support offerings for AWS itself, from free basic support through Developer and Business tiers to Enterprise Support with a named Technical Account Manager."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"AWS Marketplace","d":"AWS's software store: thousands of third-party products \u2014 security tools, databases, AI software, data sets \u2014 bought on your AWS bill."},{"f":"cloud","t":"aws-leaders","g":"Management, Cost & Strategy","n":"AWS Budgets","d":"The service that lets you set cost and usage budgets per account."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure Virtual Machines","d":"The core infrastructure service: virtual servers running Windows or Linux in Microsoft's data centres, in hundreds of size combinations tuned for general, compute."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Virtual Machine Scale Sets","d":"A way to run a group of identical VMs as one unit that automatically grows and shrinks with demand, spreading instances across fault zones for resilience."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure Functions","d":"Microsoft's serverless compute: small pieces of code that run in response to events such as a file arriving, a message landing or a timer firing."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure Container Apps","d":"A managed platform for running containers without operating a Kubernetes cluster yourself, built for microservices, APIs and background jobs that scale with demand."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"AKS","d":"Microsoft's managed Kubernetes: the platform for containerised applications at scale, with Azure handling the cluster control plane and integrating with Entra ID."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure App Service","d":"A fully managed platform for hosting web applications and APIs in .NET, Java, Node.js, Python and PHP, with deployment slots, autoscaling and authentication built in."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure Container Instances","d":"The simplest way to run a single container in Azure: no cluster, no platform, just start a container and pay while it runs."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure Batch","d":"A service for running large-scale parallel and high-performance computing jobs \u2014 rendering, risk modelling, simulations \u2014 across pools of VMs that Azure creates."},{"f":"cloud","t":"azure-leaders","g":"Compute & Containers","n":"Azure Container Registry","d":"A private registry for your organisation's container images, integrated with AKS, Container Apps and Azure DevOps pipelines, with geo-replication for global teams."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Blob Storage","d":"Azure's object storage for unstructured data: documents, images, backups, logs and the raw material of data lakes and AI training sets."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Azure Files","d":"Managed file shares in the cloud that behave like the shared drives staff already know, reachable over standard SMB and NFS protocols."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Managed Disks","d":"The virtual hard disks attached to Azure VMs, managed entirely by Microsoft so you never administer storage accounts for disks."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Azure SQL Database","d":"A fully managed relational database built on the SQL Server engine, with patching, backups, high availability and scaling handled by Microsoft."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Cosmos DB","d":"Microsoft's globally distributed, multi-model database for applications that need fast responses anywhere in the world \u2014 retail catalogues, IoT."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Azure Database for PostgreSQL","d":"A managed home for PostgreSQL, the open-source database many modern applications are built on, with Microsoft handling backups, patching and availability."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Azure Synapse Analytics","d":"Microsoft's enterprise analytics service, combining data warehousing with big-data querying so analysts can work over the data lake and the warehouse in one place."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Data Lake Storage Gen2","d":"The storage foundation for Azure analytics: Blob Storage enhanced with a hierarchical file system so big-data engines can organise and process files like a real file."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Azure Cache for Redis","d":"A managed in-memory cache based on Redis that keeps frequently used data in memory so applications answer in microseconds instead of querying the database every time."},{"f":"cloud","t":"azure-leaders","g":"Storage & Data","n":"Azure Table Storage","d":"A simple, very low-cost NoSQL store for structured key-attribute data \u2014 settings, device registries, reference tables \u2014 that does not need relational queries or joins."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Azure OpenAI Service","d":"OpenAI's models \u2014 the GPT family and related models \u2014 delivered inside Azure with enterprise controls: your data stays in your tenant, content filtering is built in."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Azure AI Search","d":"Microsoft's search service for applications and, increasingly, for AI: it indexes documents and data, including vector embeddings."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Foundry Tools (formerly Azure AI Services / Cognitive Services)","d":"A family of prebuilt AI capabilities sold as APIs \u2014 vision, speech, language."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Azure Machine Learning","d":"The platform where data science teams train, register and deploy their own machine learning models, with experiment tracking."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Microsoft Copilot Studio","d":"The low-code studio for building copilots and agents on your business data, published into Microsoft 365, Teams and the web."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Microsoft Foundry (formerly Azure AI Foundry, renamed November 2025)","d":"Microsoft's unified studio for building AI applications and agents: a catalogue of models from OpenAI, Microsoft, Meta and others, with evaluation."},{"f":"cloud","t":"azure-leaders","g":"AI & Cognitive Services","n":"Azure AI Speech","d":"Speech-to-text, text-to-speech, translation and speaker recognition as APIs, used for call-centre transcription, meeting intelligence, voice assistants and accessibility."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Virtual Network (VNet)","d":"Your private network inside Azure: the address space where VMs, containers and databases live, segmented into subnets and connected to your offices and other VNets."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Azure DNS","d":"Microsoft's hosting service for DNS domains, running on Azure's global anycast network so name lookups resolve quickly worldwide."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Azure Front Door","d":"Microsoft's global entry point for web applications: it routes users to the nearest healthy copy of your application."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Application Gateway","d":"A regional load balancer for web traffic that understands HTTP: it routes by URL path."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Azure Load Balancer","d":"The foundational traffic distributor of Azure: it spreads incoming connections across healthy VMs or containers at the network level, without inspecting content."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"ExpressRoute","d":"A private, dedicated connection between your data centre or office and Azure that never crosses the public internet, bought through a connectivity provider."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Azure Firewall","d":"Microsoft's managed network firewall: a central checkpoint that inspects and controls traffic between your Azure networks, your offices and the internet."},{"f":"cloud","t":"azure-leaders","g":"Networking","n":"Azure Bastion","d":"A managed jump box that lets administrators connect securely to VMs through the Azure portal in a browser."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Entra ID","d":"The identity service at the centre of the Microsoft cloud \u2014 formerly Azure Active Directory \u2014 holding user accounts."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Azure Key Vault","d":"The vault for the secrets of the estate: encryption keys, passwords, certificates and tokens, stored under strict access control and audit."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Microsoft Defender for Cloud","d":"Microsoft's security posture dashboard for Azure (and, via Arc, other clouds): it scores your configuration against benchmarks."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Microsoft Sentinel","d":"Microsoft's cloud-native security operations platform \u2014 a SIEM and SOAR that collects logs from across the estate."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Azure Policy","d":"The rule engine of Azure governance: policies that audit or outright block deployments breaking your standards \u2014 wrong region, unencrypted disk."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Azure RBAC","d":"The permission system that decides who can do what to which Azure resources, using roles assigned at management group, subscription."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Azure Landing Zones","d":"Microsoft's reference blueprint for a well-governed Azure foundation: how subscriptions are organised, networks connected, identity and policy applied."},{"f":"cloud","t":"azure-leaders","g":"Identity, Security & Governance","n":"Azure DDoS Protection","d":"Protection against distributed denial-of-service attacks that flood your public applications with traffic until they fall over."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Azure DevOps","d":"Microsoft's development collaboration suite \u2014 Boards for work tracking, Repos for Git, Pipelines for CI/CD."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Logic Apps","d":"A low-code integration service for connecting applications and automating workflows \u2014 when an invoice lands in one system, update another, notify a person."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Azure API Management","d":"The gateway and catalogue for your organisation's APIs: it publishes interfaces securely, controls who can call them and how often."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Service Bus","d":"Enterprise messaging for connecting systems reliably: orders, payments and commands travel as messages through queues and topics."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Event Hubs","d":"A high-throughput event streaming service that ingests millions of events per second \u2014 telemetry, clickstreams, IoT readings \u2014 for real-time analytics and processing."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Bicep","d":"Microsoft's language for defining Azure infrastructure as code: networks, VMs and policies declared in files, reviewed like software and deployed identically every time."},{"f":"cloud","t":"azure-leaders","g":"Developer & Integration","n":"Azure Event Grid","d":"The event router of Azure: it pushes notifications \u2014 a file arrived, a VM changed, a resource was created \u2014 to Functions, Logic Apps and webhooks the moment they happen."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Monitor","d":"The observability platform of Azure: it collects metrics and health signals from every service, raises alerts, and feeds the dashboards operations teams watch."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Log Analytics","d":"The log data warehouse behind Azure Monitor and Sentinel, queried in KQL, Microsoft's query language, to answer questions across millions of log records \u2014 what failed."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Cost Management","d":"Microsoft's built-in FinOps tooling: it breaks the Azure bill down by team, project and resource, sets budgets, and alerts owners before spend runs away."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Arc","d":"Microsoft's bridge for everything outside Azure: servers in your data centre or on other clouds appear inside Azure's management plane, governed by the same policy."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Migrate","d":"The migration workhorse: it discovers your on-premises servers, assesses their readiness and likely Azure cost, then replicates and moves them with minimal downtime."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Cloud Adoption Framework","d":"Microsoft's official methodology for moving to the cloud: strategy, planning, landing zones, migration, governance and management."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Hybrid Benefit","d":"A licensing benefit that lets you apply existing Windows Server and SQL Server licences \u2014 typically bought with Software Assurance \u2014 to Azure instead of paying for."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Reservations","d":"A commitment discount: promise to use a VM, database or other resource for a one- or three-year term and Microsoft charges materially less than pay-as-you-go."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Marketplace","d":"Microsoft's storefront for third-party software and services that run on Azure \u2014 security tools, databases, AI products \u2014 purchased on the same bill."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Microsoft Enterprise Agreement","d":"The multi-year volume licensing agreement through which most large organisations buy Microsoft 365, Azure and server licences together."},{"f":"cloud","t":"azure-leaders","g":"Management, Cost & Strategy","n":"Azure Advisor","d":"A built-in consultant that continuously scans your estate and recommends improvements across cost, security, reliability."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"Compute Engine","d":"Google Cloud's infrastructure-as-a-service virtual machines, running on Google's global network with custom machine types."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"Cloud Run","d":"A fully managed serverless platform that runs containerised applications and scales them from zero to thousands of instances in seconds."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"GKE","d":"A managed Kubernetes service for running containerised applications, offered in Standard mode with node control or Autopilot mode where Google manages the nodes entirely."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"App Engine","d":"Google's original platform-as-a-service, launched in 2008, where developers deploy code in standard languages and Google handles servers."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"Cloud Run Functions","d":"Google Cloud's functions-as-a-service for event-driven code, rebranded from Cloud Functions and built on Cloud Run and Eventarc in its current generation."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"TPU","d":"Google's custom chips designed exclusively for machine learning workloads, available on Google Cloud in pods that link many chips into a single training system."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"Tau VM Family","d":"A family of Compute Engine virtual machines selected purely for price-performance rather than maximum specifications, aimed at scale-out web servers."},{"f":"cloud","t":"google-cloud-leaders","g":"Compute & Containers","n":"Spot VMs","d":"Deeply discounted Compute Engine capacity that Google can reclaim with short notice when it needs the machines back, sold for fault-tolerant, batch and stateless work."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Cloud Storage","d":"Google Cloud's unified object storage for everything from data lakes to backups, offered in Standard, Nearline, Coldline and Archive classes behind a single API."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Persistent Disk","d":"Network block storage for Compute Engine and GKE, in balanced, SSD performance and extreme tiers, decoupled from the VM itself so data survives instance changes."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Filestore","d":"Fully managed NFS file storage for applications that need shared, POSIX-style file systems rather than object storage."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Cloud SQL","d":"A fully managed relational database service for MySQL, PostgreSQL and SQL Server, handling backups, replication, patching and failover."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Spanner","d":"A globally distributed relational database that combines SQL and ACID transactions with horizontal scale across continents and strong external consistency."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Bigtable","d":"A petabyte-scale, wide-column NoSQL database for high-throughput, low-latency workloads such as time series, telemetry, personalisation and fraud features."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Firestore","d":"A serverless, document-oriented NoSQL database with real-time synchronisation, offline support in mobile SDKs and automatic scaling."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"BigQuery","d":"Google Cloud's flagship serverless data warehouse, which separates storage from compute so analysts can scan petabytes with SQL in seconds without provisioning any."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Dataflow","d":"A fully managed service for stream and batch data processing built on the Apache Beam programming model."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Dataproc","d":"A managed service for running Apache Spark, Hadoop, Presto and related open-source data tools on Google Cloud infrastructure."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Pub/Sub","d":"A global, fully managed messaging service for event-driven architectures, decoupling publishers from subscribers with at-least-once and exactly-once delivery options."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Looker","d":"Google Cloud's enterprise business intelligence platform, built around LookML."},{"f":"cloud","t":"google-cloud-leaders","g":"Data & Analytics","n":"Memorystore","d":"A fully managed in-memory service for Redis and Memcached, used for caching, session stores, leaderboards and other sub-millisecond data needs."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Gemini Enterprise Agent Platform (formerly Vertex AI, renamed April 2026)","d":"Google Cloud's unified machine learning platform covering data preparation, training, tuning, deployment, monitoring and a Model Garden of first-party and open models."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Gemini Models on Gemini Enterprise Agent Platform","d":"Google's flagship multimodal model family, available through the Gemini Enterprise Agent Platform with enterprise controls."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Google AI Studio","d":"Google's free, browser-based prototyping environment for the Gemini API, aimed at developers and product teams who want to experiment with prompts and models in minutes."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Imagen & Veo","d":"Google's media generation models on the Gemini Enterprise Agent Platform: Imagen for high-quality images and Veo for video generation from text and image prompts."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Document AI","d":"A suite of document-understanding services that extract structured data from invoices, receipts, contracts."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Vision AI & Speech APIs","d":"Pre-trained API services for image labelling, OCR, face and landmark detection, speech-to-text and text-to-speech across many languages."},{"f":"cloud","t":"google-cloud-leaders","g":"AI & Machine Learning","n":"Gemini Enterprise (formerly Agentspace, renamed October 2025)","d":"Google's enterprise search and agent product that connects Gemini-powered assistants to company data across systems such as Drive, SharePoint, Jira and Salesforce."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"VPC","d":"The network that defines how Google Cloud resources connect, with a distinctive global design: one VPC can span every region, with subnets placed regionally inside it."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Cloud Load Balancing","d":"Google's global and regional load balancing services, including the Application Load Balancer that fronts production systems with a single global anycast IP address."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Cloud CDN","d":"A content delivery network that caches web and media content at Google's global edge locations, integrated with Cloud Load Balancing and signed URLs for private content."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Cloud DNS","d":"A managed, authoritative DNS service running on Google's anycast network, integrated with VPC private zones and domain registration workflows."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Cloud Armor","d":"Google Cloud's DDoS protection and web application firewall service, attached at the load balancer to filter attacks at the edge before they reach applications."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Cloud Interconnect","d":"Private, dedicated connectivity between your data centres or offices and Google Cloud."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Network Intelligence Center","d":"A single console for network observability and troubleshooting, combining topology visualisation, connectivity tests, performance dashboards and firewall insights."},{"f":"cloud","t":"google-cloud-leaders","g":"Networking & CDN","n":"Private Service Connect","d":"A networking capability that lets consumers reach Google APIs and third-party or internal services through private endpoints inside their own VPC."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"IAM","d":"The control plane for who can do what on Google Cloud, organised around an organisation."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Organization Policies","d":"Guardrail constraints applied across the organisation, folders or projects, such as restricting which regions resources can be created in."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Secret Manager","d":"A managed service for storing, versioning and controlling access to API keys, passwords, certificates and other secrets, with rotation support and full audit logging."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Cloud KMS","d":"A managed key management service for creating, rotating and governing encryption keys, with options for software keys."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Security Command Center","d":"Google Cloud's central security and risk management platform, aggregating findings on misconfigurations, vulnerabilities and threats."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Google Security Operations (formerly Chronicle)","d":"Google's cloud-native security operations platform for ingesting and searching petabytes of security telemetry at speed."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Assured Workloads","d":"A set of controls that create regulated workload folders on Google Cloud with enforced data residency."},{"f":"cloud","t":"google-cloud-leaders","g":"Security & Identity","n":"Chrome Enterprise Premium (formerly BeyondCorp Enterprise)","d":"Google's zero trust access product, built on the BeyondCorp model Google developed for its own workforce."},{"f":"cloud","t":"google-cloud-leaders","g":"Developer & Integration","n":"Apigee","d":"Google Cloud's full-lifecycle API management platform for designing, securing, publishing and analysing APIs."},{"f":"cloud","t":"google-cloud-leaders","g":"Developer & Integration","n":"Cloud Build","d":"Google Cloud's serverless continuous integration service that executes build pipelines in containers on demand."},{"f":"cloud","t":"google-cloud-leaders","g":"Developer & Integration","n":"Cloud Deploy","d":"A managed continuous delivery service that promotes container images through environments such as test, staging and production on GKE or Cloud Run, with approvals."},{"f":"cloud","t":"google-cloud-leaders","g":"Developer & Integration","n":"Firebase","d":"Google's application development platform for mobile and web apps, bundling authentication, Firestore, hosting, cloud functions."},{"f":"cloud","t":"google-cloud-leaders","g":"Developer & Integration","n":"Cloud Workstations","d":"Managed, preconfigured cloud development environments that give engineers consistent, policy-controlled workstations accessible from a browser or local IDE."},{"f":"cloud","t":"google-cloud-leaders","g":"Developer & Integration","n":"Artifact Registry","d":"Google Cloud's managed repository for container images and language packages, with vulnerability scanning and regional storage, succeeding the older Container Registry."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Cloud Monitoring","d":"Google Cloud's observability service for metrics, dashboards, uptime checks and SLO-based alerting across cloud and hybrid workloads."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Cloud Logging","d":"A fully managed log management service that ingests application, system and audit logs in real time, with log-based metrics, sinks and BigQuery-backed analysis."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Cloud Billing & Cost Management","d":"The set of billing reports, budgets, alerts, cost tables and BigQuery billing exports through which Google Cloud spending is observed and governed."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Committed Use Discounts","d":"Discounts earned by committing to use a defined amount of compute or spend for one or three years."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Sustained Use Discounts","d":"Automatic discounts applied when Compute Engine instances run for a significant portion of the month, with no commitment or action required."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"GKE Enterprise (Anthos)","d":"The enterprise tier of Google's Kubernetes platform, formerly branded Anthos, adding fleet management, centralised policy and security controls."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Google Cloud Marketplace","d":"The catalogue of third-party and Google software and services purchasable through your Google Cloud agreement, from security tools to databases and AI models."},{"f":"cloud","t":"google-cloud-leaders","g":"Management, Cost & Strategy","n":"Google Sovereign Cloud Offerings","d":"Google's portfolio of sovereignty solutions, including Google Distributed Cloud in connected and air-gapped forms and partner-operated sovereign clouds in several."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"Cybersecurity","d":"The practice of protecting systems, networks and data from digital attack, damage and unauthorised access."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"Threat","d":"Any actor or event with the potential to harm your systems or data: a criminal group, a disgruntled insider, a careless employee, or even a flood in a data centre."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"Vulnerability","d":"A weakness an attacker can use: unpatched software, a misconfigured cloud setting, a reused password, or an untrained employee."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"Risk","d":"The potential business impact if a threat successfully exploits a vulnerability: money lost, operations stopped, data exposed, penalties incurred."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"Exploit","d":"The technique or code an attacker uses to take advantage of a vulnerability, such as a malicious document that triggers a software flaw."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"Defence in Depth","d":"Layering multiple, independent security controls so that if one fails, others still protect you: MFA behind a password, segmentation behind a firewall."},{"f":"cyber","t":"cybersecurity","g":"Foundations","n":"CIA Triad","d":"The three classic security goals."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Malware","d":"Malicious software in all its forms: viruses, worms, trojans, spyware and ransomware."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Ransomware","d":"Malware that encrypts an organisation's files and systems and demands payment for the decryption key."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Phishing","d":"Fraudulent messages, usually email, that imitate trusted senders to trick people into revealing credentials, approving payments or running malware."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Spear Phishing","d":"Phishing researched and personalised for a specific person or organisation: correct names, projects, suppliers and writing style, increasingly polished with AI tools."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Social Engineering","d":"Manipulating people into giving access or information: impersonating IT support, a vendor, or a senior executive, by phone, message or email."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Zero-Day","d":"A vulnerability that is exploited before the vendor knows about it or has a patch available, giving defenders zero days to prepare."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"APT","d":"Advanced Persistent Threat: a well-resourced, often state-backed attacker who infiltrates a network quietly and stays for months."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"DDoS","d":"Distributed Denial of Service: flooding a service with traffic from many compromised devices at once until legitimate users cannot reach it."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Insider Threat","d":"Risk from people with legitimate access: a malicious employee stealing data, a departing staff member copying client lists."},{"f":"cyber","t":"cybersecurity","g":"Threats & Attacks","n":"Supply Chain Attack","d":"Compromising an organisation through its suppliers: a tampered software update, a breached managed service provider, or a malicious component in a trusted product."},{"f":"cyber","t":"cybersecurity","g":"Identity & Access","n":"IAM","d":"Identity and Access Management: the systems and processes that decide who gets an account, what it can reach, and when access is removed."},{"f":"cyber","t":"cybersecurity","g":"Identity & Access","n":"MFA","d":"Multi-Factor Authentication: requiring a password plus something else \u2014 an authenticator app, a hardware key, a biometric \u2014 before granting access."},{"f":"cyber","t":"cybersecurity","g":"Identity & Access","n":"Passkeys","d":"A modern login method using cryptographic keys stored on your device, unlocked by fingerprint, face or PIN."},{"f":"cyber","t":"cybersecurity","g":"Identity & Access","n":"SSO","d":"Single Sign-On: one verified identity that unlocks all of an employee's applications through a central provider."},{"f":"cyber","t":"cybersecurity","g":"Identity & Access","n":"PAM","d":"Privileged Access Management: extra controls for the most powerful accounts, administrators and service accounts that can change systems."},{"f":"cyber","t":"cybersecurity","g":"Identity & Access","n":"Least Privilege","d":"The principle that every person and system should have only the minimum access needed for their job, for only as long as they need it."},{"f":"cyber","t":"cybersecurity","g":"Network Security","n":"Firewall","d":"A control that inspects network traffic and blocks or allows it by rules based on source, destination and type."},{"f":"cyber","t":"cybersecurity","g":"Network Security","n":"IDS/IPS","d":"Systems that monitor network traffic for patterns of attack."},{"f":"cyber","t":"cybersecurity","g":"Network Security","n":"VPN","d":"Virtual Private Network: an encrypted tunnel between a user or site and the organisation's network, protecting traffic on untrusted networks."},{"f":"cyber","t":"cybersecurity","g":"Network Security","n":"Zero Trust","d":"A security model that assumes no user, device or network location is inherently trustworthy, so every access is verified by identity, device health and context."},{"f":"cyber","t":"cybersecurity","g":"Network Security","n":"Network Segmentation","d":"Dividing a network into separated zones with controlled traffic between them, so a compromise in one area cannot spread freely."},{"f":"cyber","t":"cybersecurity","g":"Network Security","n":"DNS Security","d":"Protecting the Domain Name System, the address book that turns names into network addresses."},{"f":"cyber","t":"cybersecurity","g":"Endpoint & Workload","n":"EDR","d":"Endpoint Detection and Response: software on laptops and servers that records behaviour, detects malicious activity that signature antivirus misses."},{"f":"cyber","t":"cybersecurity","g":"Endpoint & Workload","n":"XDR","d":"Extended Detection and Response: EDR's concept widened to correlate signals across endpoints, email, identity, network and cloud into one investigation view."},{"f":"cyber","t":"cybersecurity","g":"Endpoint & Workload","n":"Antivirus / NGAV","d":"Traditional antivirus matches files against known malware signatures; Next-Generation Antivirus (NGAV) adds behavioural analysis, machine learning and rollback."},{"f":"cyber","t":"cybersecurity","g":"Endpoint & Workload","n":"Patch Management","d":"The disciplined process of finding, testing and applying software updates that fix vulnerabilities across servers, laptops, applications and network devices."},{"f":"cyber","t":"cybersecurity","g":"Endpoint & Workload","n":"CSPM","d":"Cloud Security Posture Management: tools that continuously scan cloud accounts for misconfigurations such as publicly exposed storage."},{"f":"cyber","t":"cybersecurity","g":"Endpoint & Workload","n":"MDM","d":"Mobile Device Management: software that enrols phones, tablets and laptops so IT can enforce encryption and passcodes, push applications."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"Encryption","d":"Scrambling data with a mathematical key so only authorised holders can read it, protecting data at rest (stored), in transit (moving) and increasingly in use."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"TLS","d":"Transport Layer Security: the protocol behind the padlock in your browser, encrypting connections and verifying the identity of websites and services."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"Hashing","d":"A one-way mathematical function that turns data into a fixed fingerprint."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"PKI","d":"Public Key Infrastructure: the system of digital certificates and certificate authorities that lets strangers verify identities and encrypt to each other safely."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"DLP","d":"Tools and policies that detect and can block sensitive data, such as customer records or source code, leaving the organisation through email, cloud uploads."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"Data Classification","d":"Labelling data by sensitivity \u2014 public, internal, confidential, restricted \u2014 so people and systems know how to handle it."},{"f":"cyber","t":"cybersecurity","g":"Data Security","n":"Tokenisation","d":"Replacing sensitive values, such as card numbers, with substitute tokens that have no value outside the system, while the real data sits in a secured vault."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"SOC","d":"The team and function that monitors security alerts around the clock, triages them, and coordinates the response when something is real."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"SIEM","d":"Security Information and Event Management: a platform that collects logs from across the estate, correlates them, and raises alerts on suspicious patterns."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"SOAR","d":"Security Orchestration, Automation and Response: tooling that automates repetitive SOC work through playbooks, such as isolating a device."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"Threat Intelligence","d":"Information about current attackers, their methods and indicators of compromise, gathered from research, industry sharing and commercial feeds."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"Threat Hunting","d":"Proactively searching your environment for signs of attackers who have evaded automated detection."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"MTTD","d":"Mean Time to Detect: the average time between an attacker's first action and your organisation noticing."},{"f":"cyber","t":"cybersecurity","g":"Security Operations","n":"MTTR","d":"Mean Time to Respond (or Remediate): the average time from detecting an incident to containing and resolving it."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"OWASP Top 10","d":"The Open Web Application Security Project's well-known list of the ten most critical web application risks, such as broken access control and injection flaws."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"Secure SDLC","d":"Building security into the Software Development Life Cycle rather than testing it on at the end: threat modelling in design, secure code review and testing during build."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"DevSecOps","d":"Automating security checks inside the DevOps pipeline, scanning code, dependencies and infrastructure definitions on every change."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"Penetration Testing","d":"Authorised, simulated attacks by specialists who try to break into systems the way a real adversary would, then report what worked and how far they got."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"Red Team","d":"A group that emulates a real adversary over weeks, using any technique in scope, phishing, physical access, technical exploits."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"Blue Team","d":"The defending team: the SOC analysts, engineers and responders who build detections, monitor and repel attacks, including red team exercises."},{"f":"cyber","t":"cybersecurity","g":"Application Security","n":"Vulnerability Scanning","d":"Automated tools that sweep systems and applications for known vulnerabilities and misconfigurations, producing prioritised lists for patching."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"ISO 27001","d":"The international standard for an Information Security Management System: a structured way to identify risks and operate controls across people, process and technology."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"NIST Cybersecurity Framework","d":"A voluntary framework from the US National Institute of Standards and Technology that organises security into functions: Govern, Identify, Protect, Detect."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"SOC 2","d":"An independent audit, common for SaaS and service companies, examining controls against Trust Services Criteria, principally security, plus availability."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"GDPR","d":"The EU's General Data Protection Regulation, the reference law for personal data protection."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"Risk Assessment","d":"The structured process of identifying assets and threats, estimating likelihood and impact, and deciding what to fix, accept, transfer or avoid."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"Security Audit","d":"An independent examination of whether security controls exist and operate as claimed, internal or external."},{"f":"cyber","t":"cybersecurity","g":"Governance, Risk & Compliance","n":"CISO","d":"The Chief Information Security Officer: the executive accountable for the security programme, risk posture and incident readiness."},{"f":"cyber","t":"cybersecurity","g":"Resilience & Response","n":"Incident Response","d":"The organised process for handling a security incident: preparation, detection, containment, eradication, recovery and lessons learned."},{"f":"cyber","t":"cybersecurity","g":"Resilience & Response","n":"Digital Forensics","d":"The disciplined collection and analysis of digital evidence to establish what an attacker did, what they accessed, and whether they are truly gone."},{"f":"cyber","t":"cybersecurity","g":"Resilience & Response","n":"Backup & Recovery","d":"Copies of data and systems kept so the business can restore after ransomware, corruption or disaster."},{"f":"cyber","t":"cybersecurity","g":"Resilience & Response","n":"Business Continuity","d":"Planning how the organisation keeps essential services running during and after a crisis, cyberattack, outage or disaster."},{"f":"cyber","t":"cybersecurity","g":"Resilience & Response","n":"Security Awareness","d":"Training and culture work that helps every employee recognise and report attacks: phishing simulations, short targeted lessons, and easy reporting routes."},{"f":"cyber","t":"cybersecurity","g":"Resilience & Response","n":"Tabletop Exercise","d":"A discussion-based rehearsal of a crisis scenario, where leaders walk through a simulated ransomware attack or breach and make the decisions they would face."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"MITRE ATT&CK Framework","d":"A public knowledge base that catalogues how real attackers behave, organised as tactics (the attacker's goal at each stage) and techniques (how they achieve it)."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"Cyber Kill Chain","d":"A model that breaks an intrusion into sequential stages, from reconnaissance through delivery and exploitation to actions on the target."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"Threat Actors","d":"The people and groups behind attacks, ranging from financially motivated criminal gangs to state-sponsored espionage teams and malicious insiders."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"APT","d":"A well-resourced, usually state-backed attacker who gains access quietly and stays for months or years to steal information rather than cause immediate damage."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"TTPs","d":"The behaviour patterns of an attacker: tactics are their goals, techniques are their methods, procedures are the specific ways they carry them out."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"IOCs","d":"Observable traces that suggest a system has been compromised, such as malicious file hashes, suspicious domains, unusual IP addresses or unexpected registry changes."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"Threat Intelligence","d":"Curated information about who is attacking organisations like yours, how they operate and what to look for, turned into decisions and detections."},{"f":"cyber","t":"cyber-threats","g":"Threat Landscape","n":"Attack Surface","d":"Everything an attacker can reach or probe: internet-facing systems, cloud services, employee accounts, suppliers, forgotten test servers and exposed data."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Reconnaissance","d":"The research phase, where attackers gather information about targets: employee names and roles, technologies in use, email formats, suppliers and public documents."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"OSINT","d":"Intelligence gathered from publicly available sources: social media, public records, code repositories, leaked documents and company websites."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Attacker Vulnerability Scanning","d":"Attackers continuously scan the internet for systems with known, unpatched weaknesses, using the same vulnerability databases defenders rely on."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Exploit Public-Facing Applications","d":"Breaking in through software that is reachable from the internet by design: web applications, VPN gateways, email servers and remote-access portals."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Valid Accounts Attack","d":"Logging in with stolen or guessed credentials instead of breaking in, which makes the attacker look like a legitimate user."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Drive-By Compromise","d":"Infecting a visitor simply because they opened a compromised or malicious website, with no click on an attachment required."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Software Supply Chain Compromise","d":"Tampering with software, updates or components from a trusted supplier so the malicious code arrives through a channel the victim already trusts."},{"f":"cyber","t":"cyber-threats","g":"Recon & Initial Access","n":"Zero-Day Exploitation","d":"Attacking a software flaw before the vendor knows about it or has released a fix, so no patch exists to apply."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Phishing","d":"Fraudulent messages, usually email, that imitate trusted senders to trick people into revealing credentials, approving payments or running malicious files."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Spear Phishing","d":"Phishing aimed at a specific person, researched and written for them: correct name, role, projects, writing style and plausible context."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Whaling","d":"Spear phishing aimed at senior executives, whose authority can unlock large payments, confidential data or board-level information."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Smishing & Vishing","d":"Phishing moved to other channels: smishing uses text messages, vishing uses voice calls, often impersonating banks, delivery firms or IT help desks."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"BEC","d":"Fraud where an attacker impersonates an executive, supplier or lawyer by email to redirect a payment or extract sensitive data."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Credential Harvesting","d":"Collecting usernames and passwords through fake login pages, malicious attachments or impersonated services, so the attacker can simply log in later."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Pretexting","d":"Inventing a believable story \u2014 a pretext \u2014 to manipulate someone into giving access or information: a fake auditor, a new starter who lost their badge."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"Baiting","d":"Tempting a victim with something attractive \u2014 a labelled USB drive in the car park, a free download, a QR code on a poster \u2014 that delivers malware when used."},{"f":"cyber","t":"cyber-threats","g":"Social Engineering","n":"MFA Fatigue","d":"Flooding a victim with repeated MFA approval requests, often late at night, until they approve one just to make the phone stop."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Trojan","d":"Malicious software disguised as something legitimate: a cracked app, a fake invoice tool, a useful-looking utility."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Worm","d":"Self-spreading malware that copies itself from machine to machine without needing a victim to click anything, exploiting network weaknesses as it goes."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Rootkit","d":"Malware designed to hide deep inside a system, concealing the attacker's presence, files and other tools from security software and administrators."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Fileless Malware","d":"Attacks that operate mainly in memory and misuse legitimate system tools, leaving few or no malicious files on disk for antivirus to find."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"LotL","d":"Using the powerful tools already built into the operating system \u2014 scripting engines, management utilities, remote administration features \u2014 to carry out an attack."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Ransomware","d":"Malware that encrypts an organisation's files and systems and demands payment for the decryption key, usually after weeks of quiet intrusion to maximise damage."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"RaaS","d":"A business model where ransomware developers lease their malware and infrastructure to affiliate criminals for a share of the ransom."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Double Extortion","d":"Attackers steal data before encrypting it, then threaten to publish the data if the ransom is not paid, so even perfect backups do not end the crisis."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Data Leak Sites","d":"Websites, usually on anonymising networks, where ransomware groups publish stolen data from victims who refuse to pay."},{"f":"cyber","t":"cyber-threats","g":"Malware & Ransomware","n":"Wiper Malware","d":"Malware built purely to destroy data and systems, with no ransom and no recovery key, often disguised as ransomware to mislead responders."},{"f":"cyber","t":"cyber-threats","g":"Persistence & Evasion","n":"Persistence Mechanisms","d":"The collection of tricks attackers use to survive reboots, logoffs and password changes: hidden accounts, startup entries, scheduled jobs and modified services."},{"f":"cyber","t":"cyber-threats","g":"Persistence & Evasion","n":"Scheduled Tasks & Services","d":"Attackers commonly hide persistence inside the operating system's own scheduling and service mechanisms."},{"f":"cyber","t":"cyber-threats","g":"Persistence & Evasion","n":"Obfuscation","d":"Deliberately scrambling code, commands or traffic so humans and security tools cannot easily tell what they do: encoding, packing."},{"f":"cyber","t":"cyber-threats","g":"Persistence & Evasion","n":"Impair Defences","d":"Deliberately disabling or weakening security controls once inside: stopping antivirus, clearing policies, uninstalling monitoring agents or opening firewall rules."},{"f":"cyber","t":"cyber-threats","g":"Persistence & Evasion","n":"Bootkits & Firmware Implants","d":"Malware that lodges in the boot process or device firmware, below the operating system."},{"f":"cyber","t":"cyber-threats","g":"Persistence & Evasion","n":"Indicator Removal & Log Tampering","d":"Deleting or altering logs and other evidence to hide what happened, delay detection and frustrate the investigation that follows an incident."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Privilege Escalation","d":"Moving from an ordinary compromised account to one with administrative power, by exploiting flaws, misconfigurations or stored credentials."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Pass-the-Hash","d":"A technique for reusing a stored cryptographic fingerprint of a password to log in elsewhere, without ever knowing the actual password."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Kerberoasting","d":"Extracting encrypted service-account credentials from a Windows domain and cracking them offline at the attacker's leisure."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Golden Ticket","d":"Forging the master authentication tickets of a Windows domain after stealing its most guarded secret, granting the attacker access as almost anyone, for a very long time."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Lateral Movement","d":"The stage where an attacker moves from the first compromised machine sideways through the network toward servers, data and domain controllers."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Remote Services","d":"Attackers move between machines using the same remote-access and file-sharing services administrators use, logging in with harvested credentials."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"Domain Dominance","d":"Achieving control of the central identity system \u2014 usually the Windows domain \u2014 so the attacker can create accounts, change policies and reach every joined machine."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"C2","d":"The communication channel between malware on a victim machine and the attacker's infrastructure, used to send instructions and receive stolen data."},{"f":"cyber","t":"cyber-threats","g":"Escalation & Lateral Movement","n":"DNS","d":"Smuggling commands and stolen data inside DNS lookups, the internet's address-book traffic, which many networks allow everywhere without inspection."},{"f":"cyber","t":"cyber-threats","g":"Exfiltration & Impact","n":"Data Exfiltration","d":"Quietly copying an organisation's data out to attacker-controlled storage, using cloud uploads, file-transfer tools or the C2 channel itself."},{"f":"cyber","t":"cyber-threats","g":"Exfiltration & Impact","n":"Encryption for Impact","d":"The detonation stage of a ransomware attack, where intruders trigger encryption across as many systems as possible at once."},{"f":"cyber","t":"cyber-threats","g":"Exfiltration & Impact","n":"Backup Destruction","d":"Before encrypting, competent attackers hunt down backups, snapshots and recovery systems and delete or corrupt them."},{"f":"cyber","t":"cyber-threats","g":"Exfiltration & Impact","n":"Service Stop & Sabotage","d":"Attackers deliberately stop databases, security tools and business services before encryption."},{"f":"cyber","t":"cyber-threats","g":"Exfiltration & Impact","n":"DDoS","d":"Flooding a service with traffic from many sources to take it offline, combined with a demand for payment to stop or to prevent a larger attack."},{"f":"cyber","t":"cyber-threats","g":"Emerging & AI Threats","n":"Deepfake Fraud","d":"Using AI-generated video or audio of a real person \u2014 an executive on a video call, a finance director on the phone \u2014 to authorise payments or extract information."},{"f":"cyber","t":"cyber-threats","g":"Emerging & AI Threats","n":"Voice Cloning","d":"Creating a realistic copy of someone's voice from a short sample of real audio, then using it in calls to impersonate executives, family members or officials."},{"f":"cyber","t":"cyber-threats","g":"Emerging & AI Threats","n":"AI-Generated Phishing","d":"Phishing written or personalised by AI, removing the spelling errors and awkward phrasing people were trained to spot, and tailoring each message to its victim at scale."},{"f":"cyber","t":"cyber-threats","g":"Emerging & AI Threats","n":"Synthetic Identity Fraud","d":"Building a fake person from a mixture of real and invented details \u2014 a genuine identity number paired with a fabricated name and AI-generated face \u2014 then patiently."},{"f":"cyber","t":"cyber-threats","g":"Emerging & AI Threats","n":"AI-Driven Vulnerability Discovery","d":"Attackers and researchers alike now use AI systems to read code, hunt for flaws and generate exploit ideas far faster than manual review allowed."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"AI Attack Surface","d":"The total set of ways an organisation's AI systems can be attacked: the models, the data they train and retrieve from, the prompts and APIs that reach them."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"Shadow AI","d":"AI tools and services adopted by employees without IT or security approval: free chatbot accounts, browser extensions."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"AI Supply Chain","d":"The chain of models, datasets, libraries, plug-ins and hosted services an AI system depends on, most of them built by third parties."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"Model Provenance","d":"Knowing where a model actually came from: who trained it, on what data, through which checkpoints and conversions."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"Training Data Risk","d":"The risks carried by the data a model learns from: poisoned or manipulated samples, copyrighted or personal data included without rights."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"Exposed Inference Endpoints","d":"The APIs and interfaces through which users and applications query a model."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"Over-Privileged AI Agents","d":"AI agents and copilots granted broader permissions than their task needs: read access to whole drives, write access to production systems."},{"f":"cyber","t":"ai-cybersecurity","g":"AI as Attack Surface","n":"AI Asset Inventory","d":"A maintained register of every AI system, model, agent, dataset and AI vendor in use, with an owner, a purpose and a risk rating."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Prompt Injection","d":"An attack where a user deliberately crafts input to override an AI system's intended instructions \u2014 telling a customer-service model to ignore its rules."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Indirect Prompt Injection","d":"Malicious instructions hidden in content an AI system reads rather than in what the user types: a webpage, email."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Jailbreaking","d":"Techniques that persuade or trick a safety-trained model into producing content it was trained to refuse: role-play framings, encoded requests, multi-turn manipulation."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"System Prompt Leakage","d":"Extracting the hidden instructions that define an AI application's behaviour \u2014 its role, rules, internal tooling hints and sometimes embedded secrets or business logic."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"LLM Data Leakage","d":"An AI application revealing information it should not: another user's data pulled into a shared context, confidential documents surfaced through retrieval."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Insecure Output Handling","d":"Failures that happen when an application trusts model output without checking it: generated code executed unsanitised, output rendered as HTML enabling script injection."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Excessive Agency","d":"An AI system given more capability, autonomy or tool access than its task requires, so that a single manipulation produces outsized consequences \u2014 sending mail."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"RAG","d":"Corrupting the knowledge an AI assistant retrieves from \u2014 planting documents in a wiki."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Embedding & Vector Store Risks","d":"Risks in the infrastructure that stores AI embeddings: vector databases deployed without authentication."},{"f":"cyber","t":"ai-cybersecurity","g":"LLM & GenAI Risks","n":"Multimodal Prompt Injection","d":"Instructions hidden in images, audio, video or documents that a multimodal AI processes: text inside a screenshot, a spoken phrase in a recording."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"AI-Generated Phishing","d":"Phishing written by generative AI: fluent, personalised, error-free messages in any language."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"Deepfake Executive Fraud","d":"Synthetic audio or video impersonating a senior executive to authorise payments or extract information."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"Voice Cloning","d":"Synthesising a person's voice from a short sample of public audio \u2014 an earnings call, a podcast, a social video \u2014 well enough to fool family members."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"Synthetic Identities","d":"Fraudulent identities built from AI-generated faces, documents and histories, used to open accounts, pass onboarding checks, obtain employment."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"AI-Assisted Malware Development","d":"Attackers using AI coding tools and models to write, mutate and debug malicious code faster: polymorphic variants that evade signature detection, tailored loaders."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"AI-Driven Recon & Targeting","d":"Using AI to map targets before attacking them: scraping and synthesising public information about staff, systems, suppliers and executives into target profiles."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"Bot Automation & CAPTCHA Solving","d":"AI services and models that solve the challenges designed to separate humans from bots, enabling credential stuffing, fake account creation."},{"f":"cyber","t":"ai-cybersecurity","g":"AI-Powered Attacks","n":"AI-Driven Disinformation","d":"Synthetic text, image, audio and video campaigns that manufacture false narratives, fake grassroots support, or fraudulent market and political signals at scale."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Adversarial Examples","d":"Inputs deliberately crafted to make a model misclassify or misbehave while looking normal to humans: a subtly altered image, a rephrased sentence, a sticker on a sign."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Model Extraction","d":"Reconstructing a copy of a model \u2014 or a close substitute \u2014 by querying it systematically and learning from its answers."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Model Inversion","d":"Reconstructing information about a model's training data from its outputs \u2014 in demonstrated cases."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Membership Inference","d":"Determining whether a specific person's record was in a model's training set, by exploiting the model's subtly different confidence on data it has seen."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Data Poisoning","d":"Deliberately corrupting training or feedback data so the resulting model behaves as the attacker wants: misclassifying their content as safe, favouring their products."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Backdoor Attacks","d":"A poisoned model that behaves normally on ordinary inputs but does the attacker's bidding when a specific trigger appears \u2014 a phrase, a pixel pattern, a formatting quirk."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Evasion Attacks","d":"Modifying malicious content or behaviour just enough to slip past an AI-based detector while keeping its effect: reworded phishing, mutated malware."},{"f":"cyber","t":"ai-cybersecurity","g":"Adversarial Machine Learning","n":"Sponge Attacks","d":"Inputs crafted to make a model consume maximum computation \u2014 unusually long reasoning, pathological cases."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"AI Red Teaming","d":"Deliberately attacking your own AI systems before others do: probing for prompt injection, jailbreaks, data leakage, bias failures and unsafe actions."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"Guardrails & Content Filters","d":"The layered controls around a model that inspect inputs and outputs: classifiers that block disallowed content, injection detectors, topic restrictions."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"LLM Input & Output Validation","d":"Checking everything that enters and leaves an AI application: sanitising user input and retrieved content, constraining output formats."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"Human Oversight & Kill Switches","d":"Keeping a person able to review, override and halt AI systems: approval steps for consequential agent actions, confidence thresholds that route to humans."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"Model Drift & Behaviour Monitoring","d":"Continuously watching AI systems in production for change: degrading accuracy, shifting outputs, new failure patterns, abuse attempts and cost anomalies."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"AI Incident Response","d":"The discipline of responding when an AI system is attacked or misbehaves at scale: containing a manipulated agent, preserving prompts and logs as evidence."},{"f":"cyber","t":"ai-cybersecurity","g":"Defending AI Systems","n":"AI Sandboxing & Isolation","d":"Running AI agents and model workloads inside restricted environments \u2014 separate accounts, network segments."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"AI-Augmented SOC","d":"AI assistants inside the security operations centre that triage alerts, summarise incidents, correlate events and draft response steps."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"ML-Based Threat Detection","d":"Using machine learning to spot malicious activity that signatures miss: anomalous sequences, novel malware behaviour, suspicious command patterns."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"UEBA","d":"Analytics that build behavioural baselines for each user, device and service account, then flag meaningful deviations: unusual hours, impossible travel."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"Phishing Detection AI","d":"AI systems that analyse incoming messages for malicious intent beyond links and attachments: language patterns, sender behaviour, contextual oddity."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"Malware Classification AI","d":"Models that classify files and behaviours as malicious or benign from characteristics rather than known signatures."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"AI-Driven Vulnerability Prioritisation","d":"Using AI and threat intelligence to rank vulnerabilities by real-world exploitability and relevance to your environment, instead of raw severity scores alone."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"Threat Intelligence Automation","d":"AI that ingests the flood of threat reporting \u2014 advisories, research, dark-web chatter, vendor feeds \u2014 and extracts what is relevant to your organisation."},{"f":"cyber","t":"ai-cybersecurity","g":"AI for Defence","n":"AI-Driven Threat Hunting","d":"Proactively searching your environment for attackers already inside, with AI assisting hypothesis generation."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"OWASP","d":"The community-maintained list of the ten most critical risks in LLM applications, published by the OWASP Foundation's GenAI security project."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"MITRE ATLAS","d":"MITRE's knowledge base of adversary tactics and techniques against AI systems, modelled on the famous ATT&CK framework but covering AI-specific methods: poisoning."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"NIST AI RMF","d":"The US National Institute of Standards and Technology's voluntary framework for managing AI risk, organised around four functions: Govern, Map, Measure and Manage."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"AI Governance for Security","d":"The organisational system that keeps AI adoption secure: ownership and accountability for each AI system, approval gates before deployment, data and vendor rules."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"EU AI Act","d":"The European Union's AI Act imposes explicit security duties on high-risk AI systems, including requirements for accuracy."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"ISO/IEC 42001","d":"The international standard for an AI management system: the policies, roles, risk processes and continual-improvement loop an organisation uses to govern AI."},{"f":"cyber","t":"ai-cybersecurity","g":"Governance & Frameworks","n":"AI Incident Reporting","d":"The emerging duty \u2014 and good practice \u2014 of reporting serious AI incidents to regulators, customers and internal governance: harmful outputs at scale."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"NIST CSF","d":"The US National Institute of Standards and Technology's voluntary framework for managing cybersecurity risk, used worldwide as a common language between technical teams."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"Govern, Identify, Protect, Detect, Respond, Recover","d":"The six Functions of the NIST Cybersecurity Framework: Govern sets strategy and accountability, Identify maps assets and risks, Protect implements safeguards."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"NIST SP 800-53","d":"NIST's catalogue of over a thousand security and privacy controls for information systems."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"CIS Controls v8","d":"The Center for Internet Security's prioritised set of 18 controls and 153 safeguards, written as concrete actions rather than abstract outcomes."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"CIS Benchmarks","d":"Consensus-developed configuration guides for securely setting up more than a hundred technologies \u2014 operating systems, cloud platforms, browsers."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"COBIT","d":"ISACA's governance framework for enterprise information and technology, focused on aligning IT with business goals, managing risk and measuring performance."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"ISO/IEC 27001","d":"The international standard for an Information Security Management System: a risk-based management system for protecting confidentiality, integrity and availability."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"ISO/IEC 27002","d":"The companion guidance standard to ISO 27001: it explains each of the 93 Annex A controls in detail, with implementation guidance and examples."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"ISMS","d":"The management system at the heart of ISO 27001: the policies, risk assessments, roles."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"MITRE ATT&CK","d":"MITRE's knowledge base of real-world adversary behaviour, organised as tactics (the attacker's goal) and techniques (how they achieve it) across the attack lifecycle."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"OWASP SAMM","d":"OWASP's open maturity model for software security, covering five business functions \u2014 Governance, Design, Implementation."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"NIST Privacy Framework","d":"NIST's companion to the Cybersecurity Framework, applying the same outcome-based structure to privacy risk."},{"f":"cyber","t":"security-frameworks","g":"Core Frameworks","n":"FAIR","d":"A quantitative model for cyber risk that expresses risk in financial terms: how often a loss event is likely to occur and how much it would probably cost."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"SOC 2","d":"An attestation report from a licensed CPA firm examining an organisation's controls against AICPA's Trust Services Criteria: Security, Availability, Processing Integrity."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"SOC 1 vs SOC 2","d":"SOC 1 covers controls relevant to a customer's financial reporting \u2014 think payroll processors and payment platforms whose errors would distort accounts."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"Type I vs Type II Reports","d":"A Type I report evaluates whether controls are suitably designed at a single point in time."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"PCI DSS","d":"The Payment Card Industry Data Security Standard: mandatory security requirements for any organisation that stores, processes or transmits cardholder data."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"CSA CCM","d":"The Cloud Security Alliance's control framework for cloud computing, mapping cloud-specific controls against standards such as ISO 27001, NIST and PCI DSS."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"Cyber Essentials (UK)","d":"The UK government's baseline certification, run by the National Cyber Security Centre, covering five technical control themes: firewalls, secure configuration."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"Essential Eight (Australia)","d":"The Australian Cyber Security Centre's eight prioritised mitigation strategies \u2014 including application control, patching, restricting macros."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"CMMC","d":"The US Department of Defense programme that requires defence contractors to meet defined cybersecurity levels to win contracts handling sensitive unclassified."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"FedRAMP","d":"The US Federal Risk and Authorization Management Program: the standardised security assessment and authorisation process cloud providers must pass to sell to US federal."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"Attestation vs Certification","d":"Two different kinds of assurance that are constantly confused."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"SOC 3","d":"A general-use version of the SOC 2 report against the same Trust Services Criteria."},{"f":"cyber","t":"security-frameworks","g":"Certifications & Attestations","n":"CSA STAR","d":"The Cloud Security Alliance's public registry and assurance programme for cloud providers, built on the Cloud Controls Matrix."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"GDPR","d":"The European Union's comprehensive data protection law, in force since 25 May 2018, governing how organisations worldwide collect, use."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"GDPR Principles","d":"Article 5 of the GDPR sets seven principles for processing personal data: lawfulness, fairness and transparency; purpose limitation; data minimisation; accuracy."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"DPO","d":"A designated expert role required under the GDPR for public authorities and for organisations whose core activities involve large-scale systematic monitoring of."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"DPIA","d":"A structured assessment required by the GDPR before processing that is likely to result in high risk to individuals \u2014 such as systematic monitoring."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"HIPAA","d":"The US federal law protecting health information, whose Privacy and Security Rules bind healthcare providers, health plans, clearinghouses and their business associates."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"GLBA","d":"The US law requiring financial institutions to explain their information-sharing practices and to safeguard sensitive customer data."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"CCPA/CPRA","d":"California's privacy regime: the CCPA of 2018, substantially amended and expanded by the CPRA, effective 1 January 2023."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"Data Residency & Localisation","d":"Requirements that certain data be stored or processed within a country's borders, or simply knowledge of where data physically resides."},{"f":"cyber","t":"security-frameworks","g":"Privacy & Data Laws","n":"LGPD","d":"Brazil's comprehensive data protection law, modelled closely on the GDPR, in force since September 2020 and enforced by the national authority, ANPD."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"DORA","d":"The EU regulation making digital resilience a legal obligation for financial entities \u2014 banks, insurers, investment firms and their critical ICT suppliers."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"NIS2 Directive","d":"The EU's expanded cybersecurity directive for essential and important entities across energy, transport, health, digital infrastructure, manufacturing and more."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"SEC","d":"US rules adopted in 2023 requiring listed companies to disclose material cybersecurity incidents on Form 8-K within four business days of determining materiality."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"Basel","d":"The Basel Committee on Banking Supervision's principles for operational resilience (2021)."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"SWIFT CSCF","d":"The mandatory security framework for users of the SWIFT financial messaging network: a set of mandatory and advisory controls covering environment protection."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"NERC CIP","d":"The mandatory cybersecurity standards for North America's bulk power system, covering asset identification, electronic and physical security perimeters."},{"f":"cyber","t":"security-frameworks","g":"Sector & Regional Rules","n":"MAS TRM","d":"The Monetary Authority of Singapore's technology risk guidelines for financial institutions, setting expectations on technology governance, cyber risk management."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"DPDP Act","d":"India's first comprehensive data protection law, applying to digital personal data processed in India and to foreign processing connected with offering goods or services."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"CERT-In Directions","d":"Directions issued by India's national incident response agency in April 2022 under the IT Act, binding service providers, intermediaries, data centres."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"RBI","d":"The Reserve Bank of India's cybersecurity expectations for banks and regulated financial entities."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"SEBI CSCRF","d":"The Securities and Exchange Board of India's comprehensive framework, adopted in August 2024, for stock exchanges, depositories, brokers."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"IRDAI","d":"The Insurance Regulatory and Development Authority of India's information and cyber security guidelines for insurers, brokers and intermediaries."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"IT Act","d":"India's foundational law for electronic commerce and cybercrime."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"Data Protection Board of India","d":"The adjudicatory body created by the DPDP Act to handle complaints, inquire into personal data breaches and impose penalties."},{"f":"cyber","t":"security-frameworks","g":"India \u2014 Laws & Regulators","n":"NCIIPC","d":"The National Critical Information Infrastructure Protection Centre."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"GRC","d":"The integrated discipline \u2014 and the software category named after it \u2014 that connects governance structures."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"Control Mapping","d":"The practice of relating controls across frameworks \u2014 showing, for example, that your access-control implementation satisfies requirements in ISO 27001, SOC 2."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"Maturity Models","d":"Structured scales that describe how capable a security or governance process is, from ad hoc and reactive to measured and continuously improving."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"Internal, External & Customer Audits","d":"Three distinct assurance streams most organisations now juggle: internal audits by their own independent function."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"Continuous Compliance","d":"The shift from point-in-time audit preparation to continuously monitoring whether controls are operating \u2014 automatically collecting evidence from cloud platforms."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"Compliance vs Security","d":"The persistent gap between satisfying an audit and resisting an attack."},{"f":"cyber","t":"security-frameworks","g":"Governance in Practice","n":"TPRM","d":"The governance discipline for security risk created by vendors, cloud services, processors and their own subcontractors ('fourth parties')."}];
